const r = await tools.exec_command({"cmd":"python3 - <<'PY'
import csv, collections, datetime
p='/tmp/codex-diag.0Kwe6f/audit_log.csv'
rows=list(csv.DictReader(open(p,newline='',encoding='utf-8')))
for key in ('action','state','reason'):
    c=collections.Counter(r[key] for r in rows)
    print('\n'+key, len(c))
    for k,n in c.most_common(40): print(n, repr(k))
print('\ntime range')
for t in (min(int(r['created_at']) for r in rows),max(int(r['created_at']) for r in rows)):
    print(t, datetime.datetime.fromtimestamp(t,datetime.timezone.utc).astimezone().isoformat())
PY","workdir":"/workspace","yield_time_ms":10000,"max_output_tokens":20000}); text(r.output);

const r = await tools.exec_command({"cmd":"python3 - <<'PY'
import csv,json,collections,datetime
rows=list(csv.DictReader(open('/tmp/codex-diag.0Kwe6f/audit_log.csv',newline='',encoding='utf-8')))
need=lambda r: ('429' in r['reason'] or 'mapped_session' in r['action'] or 'tool_context' in r['action'] or 'stream_stall' in r['action'] or 'native_continue' in r['action'] or r['reason'] in {'context canceled','usage_limit','bound_account_unavailable'})
for r in filter(need,rows):
    try: d=json.loads(r['detail']) if r['detail'] else {}
    except Exception: d={'_raw_type':'non-json'}
    ts=datetime.datetime.fromtimestamp(int(r['created_at']),datetime.timezone.utc).astimezone().isoformat()
    vals={k:v for k,v in d.items() if k in {'tree_hmac_prefix','namespace_hmac_prefix','epoch','old_epoch','new_epoch','status_code','attempt','max_attempts','transport','entrypoint','provider','model','account_code','recovery','reason','stage','wait_seconds','retry_after_seconds','goal_id','unpaired_tool_results','has_unpaired_tool_results','previous_response_id_present','turn_state_present','rotation_reason','from_account_code','to_account_code'}}
    print(ts,r['account_code'],r['action'],r['state'],r['reason'],'keys='+','.join(sorted(d)), 'vals='+json.dumps(vals,ensure_ascii=False,sort_keys=True))
PY","workdir":"/workspace","yield_time_ms":10000,"max_output_tokens":30000}); text(r.output);

