for r in rows:
 if not r['action'].startswith('goal_'): continue
 m=re.search(r'goal=(goal_[0-9a-f]+)',r['detail']);
 if not m: continue
 g=m.group(1); s=stat.setdefault(g,{'events':0,'checkpoints':0,'bytes':0,'maxseg':0,'starts':0,'completed':0})
 s['events']+=1
 if r['action']=='goal_checkpoint_committed':
  s['checkpoints']+=1
  m2=re.search(r'bytes=(\d+)',r['detail']); s['bytes']+=int(m2.group(1)) if m2 else 0
  m2=re.search(r'segment=(\d+)',r['detail']); s['maxseg']=max(s['maxseg'],int(m2.group(1)) if m2 else 0)
 if r['action']=='goal_compaction_started': s['starts']+=1
 if r['action']=='goal_compaction_completed': s['completed']+=1
print('goals',len(stat))
for i,(g,s) in enumerate(sorted(stat.items(),key=lambda kv:(kv[1]['checkpoints'],kv[1]['bytes']),reverse=True)[:20],1):
 print(i,'goal#',g[-6:],'events',s['events'],'checkpoints',s['checkpoints'],'max_segment',s['maxseg'],'bytes',s['bytes'],'compactions',s['starts'],s['completed'])
starts=[]
for r in rows:
 if r['action']=='goal_compaction_started':
  m=re.search(r'segments=(\d+)',r['detail']);
  if m: starts.append(int(m.group(1)))
print('compaction start segment counts: n',len(starts),'min',min(starts),'median',statistics.median(starts),'p90',sorted(starts)[int(.9*(len(starts)-1))],'max',max(starts))
