ON CONFLICT(usage_event_id) WHERE usage_event_id <> '' DO UPDATE SET
 account_id=excluded.account_id, route_key_hash=excluded.route_key_hash, api_key_hash=excluded.api_key_hash, user_id=excluded.user_id,
