const DefaultChunkSize = 64 << 10

var (
	ErrBodyTooLarge = errors.New("request body too large")
	ErrMemoryBudget = errors.New("request body memory budget exhausted")
	ErrSpoolBudget  = errors.New("request body spool budget exhausted")
	ErrDiskReserve  = errors.New("request body spool disk reserve reached")
)

type Budget struct {
	memoryLimit int64
	spoolLimit  int64
	memoryUsed  atomic.Int64
	spoolUsed   atomic.Int64
}

type BudgetSnapshot struct {
	MemoryLimit int64
	MemoryUsed  int64
	SpoolLimit  int64
	SpoolUsed   int64
}

func NewBudget(memoryLimit, spoolLimit int64) *Budget {
	return &Budget{memoryLimit: max64(memoryLimit, 0), spoolLimit: max64(spoolLimit, 0)}
}

func (b *Budget) Snapshot() BudgetSnapshot {
	if b == nil {
		return BudgetSnapshot{}
	}
	return BudgetSnapshot{MemoryLimit: b.memoryLimit, MemoryUsed: b.memoryUsed.Load(), SpoolLimit: b.spoolLimit, SpoolUsed: b.spoolUsed.Load()}
}

func (b *Budget) reserveMemory(n int64) bool {
	return b == nil || reserve(&b.memoryUsed, b.memoryLimit, n)
}
func (b *Budget) reserveSpool(n int64) bool {
	return b == nil || reserve(&b.spoolUsed, b.spoolLimit, n)
}
func (b *Budget) releaseMemory(n int64) {
	if b != nil && n > 0 {
		b.memoryUsed.Add(-n)
	}
}
func (b *Budget) releaseSpool(n int64) {
	if b != nil && n > 0 {
		b.spoolUsed.Add(-n)
	}
}

func reserve(used *atomic.Int64, limit, n int64) bool {
	if n <= 0 {
		return true
	}
	for {
		current := used.Load()
		if limit > 0 && (current > limit-n) {
			return false
		}
		if used.CompareAndSwap(current, current+n) {
			return true
		}
	}
}

type CaptureOptions struct {
	MaxBytes           int64
	MemoryThreshold    int64
	ChunkSize          int
	TempDir            string
	MinDiskFreeBytes   int64
	Budget             *Budget
	TempFileNamePrefix string
}

// Capture reads src once and chooses chunked memory or a single spool file.
func Capture(ctx context.Context, src io.Reader, options CaptureOptions) (BodySource, error) {
	if src == nil {
		return Empty(), nil
	}
	chunkSize := options.ChunkSize
	if chunkSize <= 0 {
		chunkSize = DefaultChunkSize
	}
	threshold := options.MemoryThreshold
	if threshold < 0 {
		threshold = 0
	}
	if options.MaxBytes <= 0 {
		return nil, ErrBodyTooLarge
	}
	prefix := options.TempFileNamePrefix
	if prefix == "" {
		prefix = "codex-pool-body-*"
	}
	var chunks [][]byte
	var size, memoryReserved, spoolReserved int64
	var file *os.File
	cleanup := func() {
		options.Budget.releaseMemory(memoryReserved)
		options.Budget.releaseSpool(spoolReserved)
		if file != nil {
			name := file.Name()
			_ = file.Close()
			_ = os.Remove(name)
		}
	}
	spill := func() error {
		if file != nil {
			return nil
		}
		if err := ensureDiskReserve(options.TempDir, options.MinDiskFreeBytes, options.MaxBytes); err != nil {
			return err
		}
		if !options.Budget.reserveSpool(size) {
			return ErrSpoolBudget
		}
		spoolReserved = size
		var err error
		file, err = os.CreateTemp(options.TempDir, prefix)
		if err != nil {
			return err
		}
		for _, chunk := range chunks {
			if _, err = file.Write(chunk); err != nil {
				return err
			}
		}
		chunks = nil
		options.Budget.releaseMemory(memoryReserved)
		memoryReserved = 0
		return nil
	}
	var spoolBuffer []byte
	for {
		if err := ctx.Err(); err != nil {
			cleanup()
			return nil, err
		}
		var chunk []byte
		if file != nil {
			if spoolBuffer == nil {
				spoolBuffer = make([]byte, chunkSize)
			}
			chunk = spoolBuffer
		} else {
			chunk = make([]byte, chunkSize)
		}
		n, err := src.Read(chunk)
		if n > 0 {
			if int64(n) > options.MaxBytes-size {
				cleanup()
				return nil, ErrBodyTooLarge
			}
			chunk = chunk[:n]
			if file == nil && size+int64(n) <= threshold && options.Budget.reserveMemory(int64(n)) {
				memoryReserved += int64(n)
				chunks = append(chunks, chunk)
			} else {
				if spillErr := spill(); spillErr != nil {
					cleanup()
					return nil, spillErr
				}
				if !options.Budget.reserveSpool(int64(n)) {
					cleanup()
					return nil, ErrSpoolBudget
				}
				spoolReserved += int64(n)
				if _, writeErr := file.Write(chunk); writeErr != nil {
					cleanup()
					return nil, writeErr
				}
			}
			size += int64(n)
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			cleanup()
			return nil, err
		}
		if n == 0 {
			continue
		}
	}
	if file == nil {
		return &memorySource{chunks: chunks, size: size, budget: options.Budget, reserved: memoryReserved}, nil
	}
	path := file.Name()
	if err := file.Sync(); err != nil {
		cleanup()
		return nil, err
	}
	if err := file.Close(); err != nil {
		cleanup()
		return nil, err
	}
	file = nil
	return &fileSource{path: path, size: size, remove: true, budget: options.Budget, reserved: spoolReserved}, nil
}

func ensureDiskReserve(dir string, reserveBytes, incoming int64) error {
	if reserveBytes <= 0 {
		return nil
	}
	if dir == "" {
		dir = os.TempDir()
	}
	dir, err := filepath.Abs(dir)
	if err != nil {
		return err
	}
	var stat syscall.Statfs_t
	if err = syscall.Statfs(dir, &stat); err != nil {
		return fmt.Errorf("stat spool filesystem: %w", err)
	}
	available := int64(stat.Bavail) * int64(stat.Bsize)
	if available-incoming < reserveBytes {
		return ErrDiskReserve
	}
	return nil
}

func max64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}
package bodysource

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"sort"
	"strconv"
	"sync"
)

type Patch struct {
	Offset int64
	Delete int64
	Insert BodySource
}

type JSONFieldPatch struct {
	Name   string
	Value  []byte
	Delete bool
}

// PatchTopLevel applies ordered top-level JSON field changes without materializing source.
func PatchTopLevel(source BodySource, meta BodyMeta, fields []JSONFieldPatch) (BodySource, error) {
	if source == nil || meta.ObjectEnd < 0 || meta.ObjectEnd > source.Size() {
		return nil, errors.New("invalid JSON patch source")
	}
	deletes := make([]Span, 0, len(fields))
	sets := make([]Patch, 0, len(fields)+1)
	inserted := make([]JSONFieldPatch, 0, len(fields))
	deleted := make(map[string]bool)
	seen := make(map[string]bool)
	for _, field := range fields {
		if field.Name == "" || seen[field.Name] {
			return nil, fmt.Errorf("duplicate JSON field patch %q", field.Name)
		}
		seen[field.Name] = true
		value, exists := meta.Fields[field.Name]
		if field.Delete {
			if member, ok := meta.Members[field.Name]; ok {
				deletes = append(deletes, member)
				deleted[field.Name] = true
			}
			continue
		}
		if !json.Valid(field.Value) {
			return nil, fmt.Errorf("invalid JSON value for field %q", field.Name)
		}
		if exists {
			sets = append(sets, Patch{Offset: value.Offset, Delete: value.Length, Insert: Bytes(field.Value)})
		} else {
			inserted = append(inserted, field)
		}
	}
	sort.Slice(deletes, func(i, j int) bool { return deletes[i].Offset < deletes[j].Offset })
	merged := deletes[:0]
	for _, span := range deletes {
		if len(merged) == 0 || span.Offset > merged[len(merged)-1].Offset+merged[len(merged)-1].Length {
			merged = append(merged, span)
			continue
		}
		end := span.Offset + span.Length
		if currentEnd := merged[len(merged)-1].Offset + merged[len(merged)-1].Length; end > currentEnd {
			merged[len(merged)-1].Length = end - merged[len(merged)-1].Offset
		}
	}
	for _, span := range merged {
		sets = append(sets, Patch{Offset: span.Offset, Delete: span.Length})
	}
	if len(inserted) > 0 {
		var payload bytes.Buffer
		if meta.MemberCount-len(deleted) > 0 {
			payload.WriteByte(',')
		}
		for i, field := range inserted {
			if i > 0 {
				payload.WriteByte(',')
			}
			payload.WriteString(strconv.Quote(field.Name))
			payload.WriteByte(':')
			payload.Write(field.Value)
		}
		sets = append(sets, Patch{Offset: meta.ObjectEnd, Insert: Bytes(payload.Bytes())})
	}
	sort.SliceStable(sets, func(i, j int) bool { return sets[i].Offset < sets[j].Offset })
	return Patched(source, sets)
}

// Patched creates an owning composite source. Patches must be ordered and non-overlapping.
func Patched(base BodySource, patches []Patch) (BodySource, error) {
	if base == nil {
		return nil, errors.New("nil patch base")
	}
	copyPatches := append([]Patch(nil), patches...)
	var cursor, size int64
	for i, patch := range copyPatches {
		if patch.Offset < cursor || patch.Offset < 0 || patch.Delete < 0 || patch.Offset > base.Size() || patch.Delete > base.Size()-patch.Offset {
			return nil, fmt.Errorf("invalid body patch %d", i)
		}
		cursor = patch.Offset + patch.Delete
		size -= patch.Delete
		if patch.Insert != nil {
			size += patch.Insert.Size()
		}
	}
	return &patchedSource{base: base, patches: copyPatches, size: base.Size() + size}, nil
}

type patchedSource struct {
	base    BodySource
	patches []Patch
	size    int64
	once    sync.Once
	err     error
}

func (s *patchedSource) Size() int64 { return s.size }

func (s *patchedSource) Open() (io.ReadCloser, error) {
	base, err := s.base.Open()
	if err != nil {
		return nil, err
	}
	return &patchReader{base: base, patches: s.patches}, nil
}

func (s *patchedSource) Close() error {
	s.once.Do(func() {
		s.err = s.base.Close()
		for _, patch := range s.patches {
			if patch.Insert != nil {
				s.err = errors.Join(s.err, patch.Insert.Close())
			}
		}
	})
	return s.err
}

type patchReader struct {
	base       io.ReadCloser
	patches    []Patch
	patch      int
	baseOffset int64
	segment    io.ReadCloser
	remaining  int64
	done       bool
}

func (r *patchReader) Read(p []byte) (int, error) {
	for {
		if r.done {
			return 0, io.EOF
		}
		if r.segment != nil {
			n, err := r.segment.Read(p)
			if err == io.EOF {
				_ = r.segment.Close()
				r.segment = nil
				if n > 0 {
					return n, nil
				}
				continue
			}
			return n, err
		}
		if r.remaining > 0 {
			limit := int64(len(p))
			if limit > r.remaining {
				limit = r.remaining
			}
			n, err := r.base.Read(p[:limit])
			r.baseOffset += int64(n)
			r.remaining -= int64(n)
			if err == io.EOF && r.remaining > 0 {
				return n, io.ErrUnexpectedEOF
			}
			if n > 0 || err != nil {
				return n, err
			}
			continue
		}
		if r.patch >= len(r.patches) {
			n, err := r.base.Read(p)
			r.baseOffset += int64(n)
			if err == io.EOF {
				r.done = true
			}
			return n, err
		}
		patch := r.patches[r.patch]
		if r.baseOffset < patch.Offset {
			r.remaining = patch.Offset - r.baseOffset
			continue
		}
		if patch.Delete > 0 {
			if _, err := io.CopyN(io.Discard, r.base, patch.Delete); err != nil {
				return 0, err
			}
			r.baseOffset += patch.Delete
		}
		r.patch++
		if patch.Insert != nil && patch.Insert.Size() > 0 {
			var err error
			r.segment, err = patch.Insert.Open()
			if err != nil {
				return 0, err
			}
		}
	}
}

func (r *patchReader) Close() error {
	var err error
	if r.segment != nil {
		err = r.segment.Close()
		r.segment = nil
	}
	return errors.Join(err, r.base.Close())
}

