type capturedRequest struct {
	Path          string
	Method        string
	AccountID     string
	Auth          string
	Beta          string
	Body          string
	TurnState     string
	ClaudeSession string
}

type testHarness struct {
	pool     *httptest.Server
	upstream *httptest.Server
	store    *storage.Store
	captured *[]capturedRequest
	app      *Server
}

// skipLegacyCodexContextReplay marks v1 tests that asserted journal reconstruction,
// tool-output neutralization, or account migration for a previous_response_id.
// CPA-v2 intentionally makes those stateful failures visible and pins them to one
// exact mapped account/egress; focused coverage is in codex_session_mapping_test.go.
func skipLegacyCodexContextReplay(t *testing.T) {
	t.Helper()
	t.Skip("Codex journal/degraded replay was retired in favor of strict CPA-v2 mapping")
}

func newHarness(t *testing.T, upstreamHandler http.HandlerFunc) *testHarness {
	t.Helper()
	var mu sync.Mutex
	var captured []capturedRequest
	up := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		raw, _ := io.ReadAll(r.Body)
		mu.Lock()
		captured = append(captured, capturedRequest{
			Path:          r.URL.Path,
			Method:        r.Method,
			AccountID:     r.Header.Get("ChatGPT-Account-ID"),
			Auth:          r.Header.Get("Authorization"),
			Beta:          r.Header.Get("Anthropic-Beta"),
			Body:          string(raw),
			TurnState:     r.Header.Get("X-Codex-Turn-State"),
			ClaudeSession: r.Header.Get("X-Claude-Code-Session-Id"),
		})
		mu.Unlock()
		r.Body = io.NopCloser(bytes.NewReader(raw))
		upstreamHandler(w, r)
	}))
	store, err := storage.Open(filepath.Join(t.TempDir(), "pool.sqlite3"))
	if err != nil {
		t.Fatal(err)
	}
	if err := store.Init(context.Background()); err != nil {
		t.Fatal(err)
	}
	cfg := config.Default()
	cfg.UpstreamBaseURL = up.URL + "/backend-api/codex"
	cfg.OpenAIAPIUpstreamBaseURL = up.URL + "/v1"
	cfg.ClaudeUpstreamBaseURL = up.URL
	cfg.DatabasePath = filepath.Join(t.TempDir(), "unused.sqlite3")
	cfg.StickyWaitMillis = 1
	// The production default is now the in-process TLS fingerprinter
	// (EgressFingerprintEngine="inprocess"), which dials a REAL TLS connection and
	// cannot be exercised against these httptest mock upstreams / mock sidecars.
	// This harness validates the sidecar /proxy wire protocol, so route
	// curl_cffi_sidecar egresses through the (mockable) sidecar engine. Inert for
	// direct-egress tests — the engine selector only branches on sidecar egress.
	cfg.EgressFingerprintEngine = "sidecar"
	// Most long-standing gateway tests exercise the retired compatibility engine
	// explicitly. Keep that harness opt-out scoped to those tests; CPA-v2 tests
	// enable the production default through enableCodexSessionMappingForTest.
	cfg.CodexSessionMappingEnabled = false
	cfg.CodexCPAStrict = false
	app := NewServer(Dependencies{
		Config:    cfg,
		Store:     store,
		Scheduler: scheduler.New(store, cfg),
		Upstream:  upstream.NewClient(cfg),
		Planner:   virtual.NewPlanner(store, cfg),
	})
	pool := httptest.NewServer(app)
	t.Cleanup(func() {
		pool.Close()
		up.Close()
		_ = store.Close()
	})
	return &testHarness{pool: pool, upstream: up, store: store, captured: &captured, app: app}
}

func (h *testHarness) importAccount(t *testing.T, label, upstreamAccountID, accessToken string) string {
	t.Helper()
	payload := map[string]interface{}{
		"label": label,
		"auth_json": map[string]interface{}{
			"OPENAI_API_KEY": accessToken,
			"tokens": map[string]interface{}{
				"access_token":  accessToken,
				"refresh_token": "refresh-" + label,
				"account_id":    upstreamAccountID,
			},
		},
	}
	raw, _ := json.Marshal(payload)
	resp, err := http.Post(h.pool.URL+"/admin/accounts/import-auth-json", "application/json", bytes.NewReader(raw))
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		t.Fatalf("import status %d: %s", resp.StatusCode, body)
	}
	var account storage.Account
	if err := json.NewDecoder(resp.Body).Decode(&account); err != nil {
		t.Fatal(err)
	}
	return account.ID
}

func (h *testHarness) requests() []capturedRequest {
	return append([]capturedRequest(nil), (*h.captured)...)
}

func cacheControlCountPrompt(t *testing.T, body []byte) int {
	t.Helper()
	var root map[string]interface{}
	if err := json.Unmarshal(body, &root); err != nil {
		t.Fatal(err)
	}
	countList := func(v interface{}) int {
		n := 0
		for _, item := range toInterfaceSlice(v) {
			block, ok := item.(map[string]interface{})
			if !ok {
				continue
			}
			if _, has := block["cache_control"]; has {
				n++
			}
		}
		return n
	}
	n := countList(root["system"]) + countList(root["tools"])
	for _, item := range toInterfaceSlice(root["messages"]) {
		msg, ok := item.(map[string]interface{})
		if !ok {
			continue
		}
		if _, has := msg["cache_control"]; has {
			n++
		}
		n += countList(msg["content"])
	}
	return n
}

func toInterfaceSlice(v interface{}) []interface{} {
	arr, _ := v.([]interface{})
	return arr
}

