func writeCodexSidecarStreamFailure(w io.Writer, id, model, _ string) error {
	response := map[string]interface{}{
		"id":     firstNonEmpty(strings.TrimSpace(id), "resp_pool_sidecar_stream"),
		"object": "response",
		"status": "failed",
		"error": map[string]string{
