	}
	defer first.Release()
	second, err := s.Select(ctx, Route{Group: group, Provider: "codex", Model: model})
	if err != nil {
		t.Fatal(err)
	}
	defer second.Release()

	snapshot, err := s.ProviderPressureSnapshot(ctx, group, "codex", model)
