	Open() (io.ReadCloser, error)
	Close() error
}

// Bytes references b without copying it. The caller must not mutate b while the source is in use.
func Bytes(b []byte) BodySource { return &memorySource{chunks: [][]byte{b}, size: int64(len(b))} }

// Empty returns a reusable empty body.
func Empty() BodySource { return Bytes(nil) }

type memorySource struct {
	chunks   [][]byte
	size     int64
	budget   *Budget
	reserved int64
	once     sync.Once
	closed   bool
	mu       sync.RWMutex
}

func (s *memorySource) Size() int64 { return s.size }

func (s *memorySource) Open() (io.ReadCloser, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if s.closed {
		return nil, ErrClosed
	}
	return &chunkReader{chunks: s.chunks}, nil
}

func (s *memorySource) Close() error {
	s.once.Do(func() {
		s.mu.Lock()
		s.closed = true
		s.chunks = nil
		s.mu.Unlock()
		if s.budget != nil {
			s.budget.releaseMemory(s.reserved)
		}
	})
	return nil
}

type chunkReader struct {
	chunks [][]byte
	chunk  int
	offset int
}

func (r *chunkReader) Read(p []byte) (int, error) {
	for r.chunk < len(r.chunks) {
		n := copy(p, r.chunks[r.chunk][r.offset:])
		r.offset += n
		if r.offset == len(r.chunks[r.chunk]) {
			r.chunk++
			r.offset = 0
		}
		if n > 0 {
			return n, nil
		}
	}
	return 0, io.EOF
}

func (r *chunkReader) Close() error { return nil }

type fileSource struct {
	path     string
	size     int64
	remove   bool
	budget   *Budget
	reserved int64
	once     sync.Once
	mu       sync.RWMutex
	closed   bool
	err      error
}

func (s *fileSource) Size() int64 { return s.size }

func (s *fileSource) Open() (io.ReadCloser, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if s.closed {
		return nil, ErrClosed
	}
	return os.Open(s.path)
}

func (s *fileSource) Close() error {
	s.once.Do(func() {
		s.mu.Lock()
		s.closed = true
		s.mu.Unlock()
		if s.remove {
			s.err = os.Remove(s.path)
			if errors.Is(s.err, os.ErrNotExist) {
				s.err = nil
			}
		}
		if s.budget != nil {
			s.budget.releaseSpool(s.reserved)
		}
	})
	return s.err
}

// Slice returns a non-owning view of source. Closing the view does not close source.
func Slice(source BodySource, offset, size int64) (BodySource, error) {
	if source == nil || offset < 0 || size < 0 || offset > source.Size() || size > source.Size()-offset {
		return nil, fmt.Errorf("invalid body slice offset=%d size=%d", offset, size)
	}
	return &sliceSource{source: source, offset: offset, size: size}, nil
}

type sliceSource struct {
	source BodySource
	offset int64
	size   int64
}

func (s *sliceSource) Size() int64 { return s.size }

func (s *sliceSource) Open() (io.ReadCloser, error) {
	r, err := s.source.Open()
	if err != nil {
		return nil, err
	}
	if seeker, ok := r.(io.Seeker); ok {
		_, err = seeker.Seek(s.offset, io.SeekStart)
	} else {
		_, err = io.CopyN(io.Discard, r, s.offset)
	}
	if err != nil {
		_ = r.Close()
		return nil, err
	}
	return &limitedReadCloser{Reader: io.LimitReader(r, s.size), closer: r}, nil
}

func (s *sliceSource) Close() error { return nil }

type limitedReadCloser struct {
	io.Reader
	closer io.Closer
}

func (r *limitedReadCloser) Close() error { return r.closer.Close() }

// ReadAll opens source and returns its complete contents, rejecting impossible sizes first.
func ReadAll(source BodySource) ([]byte, error) {
	if source == nil || source.Size() == 0 {
		return nil, nil
	}
	if source.Size() > int64(int(^uint(0)>>1)) {
		return nil, errors.New("body is too large for memory")
	}
	r, err := source.Open()
	if err != nil {
		return nil, err
	}
	defer r.Close()
	var out bytes.Buffer
	out.Grow(int(source.Size()))
	if _, err = io.Copy(&out, r); err != nil {
		return nil, err
	}
	if int64(out.Len()) != source.Size() {
		return nil, fmt.Errorf("body size changed: got %d want %d", out.Len(), source.Size())
	}
	return out.Bytes(), nil
}
package bodysource

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sync/atomic"
	"syscall"
)

const DefaultChunkSize = 64 << 10

var (
	ErrBodyTooLarge = errors.New("request body too large")
	ErrMemoryBudget = errors.New("request body memory budget exhausted")
	ErrSpoolBudget  = errors.New("request body spool budget exhausted")
	ErrDiskReserve  = errors.New("request body spool disk reserve reached")
)

type Budget struct {
	memoryLimit int64
	spoolLimit  int64
	memoryUsed  atomic.Int64
	spoolUsed   atomic.Int64
}

type BudgetSnapshot struct {
	MemoryLimit int64
	MemoryUsed  int64
	SpoolLimit  int64
	SpoolUsed   int64
}

func NewBudget(memoryLimit, spoolLimit int64) *Budget {
	return &Budget{memoryLimit: max64(memoryLimit, 0), spoolLimit: max64(spoolLimit, 0)}
}

func (b *Budget) Snapshot() BudgetSnapshot {
	if b == nil {
		return BudgetSnapshot{}
	}
	return BudgetSnapshot{MemoryLimit: b.memoryLimit, MemoryUsed: b.memoryUsed.Load(), SpoolLimit: b.spoolLimit, SpoolUsed: b.spoolUsed.Load()}
}

func (b *Budget) reserveMemory(n int64) bool {
	return b == nil || reserve(&b.memoryUsed, b.memoryLimit, n)
}
func (b *Budget) reserveSpool(n int64) bool {
	return b == nil || reserve(&b.spoolUsed, b.spoolLimit, n)
}
func (b *Budget) releaseMemory(n int64) {
	if b != nil && n > 0 {
		b.memoryUsed.Add(-n)
	}
}
func (b *Budget) releaseSpool(n int64) {
	if b != nil && n > 0 {
		b.spoolUsed.Add(-n)
	}
}

func reserve(used *atomic.Int64, limit, n int64) bool {
	if n <= 0 {
		return true
	}
	for {
		current := used.Load()
		if limit > 0 && (current > limit-n) {
			return false
		}
		if used.CompareAndSwap(current, current+n) {
			return true
		}
	}
}

type CaptureOptions struct {
	MaxBytes           int64
	MemoryThreshold    int64
	ChunkSize          int
	TempDir            string
	MinDiskFreeBytes   int64
	Budget             *Budget
	TempFileNamePrefix string
}

// Capture reads src once and chooses chunked memory or a single spool file.
func Capture(ctx context.Context, src io.Reader, options CaptureOptions) (BodySource, error) {
	if src == nil {
		return Empty(), nil
	}
	chunkSize := options.ChunkSize
	if chunkSize <= 0 {
		chunkSize = DefaultChunkSize
	}
	threshold := options.MemoryThreshold
	if threshold < 0 {
		threshold = 0
	}
	if options.MaxBytes <= 0 {
		return nil, ErrBodyTooLarge
	}
	prefix := options.TempFileNamePrefix
	if prefix == "" {
		prefix = "codex-pool-body-*"
	}
	var chunks [][]byte
	var size, memoryReserved, spoolReserved int64
	var file *os.File
	cleanup := func() {
		options.Budget.releaseMemory(memoryReserved)
		options.Budget.releaseSpool(spoolReserved)
		if file != nil {
			name := file.Name()
			_ = file.Close()
			_ = os.Remove(name)
		}
	}
	spill := func() error {
		if file != nil {
			return nil
		}
		if err := ensureDiskReserve(options.TempDir, options.MinDiskFreeBytes, options.MaxBytes); err != nil {
			return err
		}
		if !options.Budget.reserveSpool(size) {
			return ErrSpoolBudget
		}
		spoolReserved = size
		var err error
		file, err = os.CreateTemp(options.TempDir, prefix)
		if err != nil {
			return err
		}
		for _, chunk := range chunks {
			if _, err = file.Write(chunk); err != nil {
				return err
			}
		}
		chunks = nil
		options.Budget.releaseMemory(memoryReserved)
		memoryReserved = 0
		return nil
	}
	var spoolBuffer []byte
	for {
		if err := ctx.Err(); err != nil {
			cleanup()
			return nil, err
		}
		var chunk []byte
		if file != nil {
			if spoolBuffer == nil {
				spoolBuffer = make([]byte, chunkSize)
			}
			chunk = spoolBuffer
		} else {
			chunk = make([]byte, chunkSize)
		}
		n, err := src.Read(chunk)
		if n > 0 {
			if int64(n) > options.MaxBytes-size {
				cleanup()
				return nil, ErrBodyTooLarge
			}
			chunk = chunk[:n]
			if file == nil && size+int64(n) <= threshold && options.Budget.reserveMemory(int64(n)) {
				memoryReserved += int64(n)
				chunks = append(chunks, chunk)
			} else {
				if spillErr := spill(); spillErr != nil {
					cleanup()
					return nil, spillErr
				}
				if !options.Budget.reserveSpool(int64(n)) {
					cleanup()
					return nil, ErrSpoolBudget
				}
				spoolReserved += int64(n)
				if _, writeErr := file.Write(chunk); writeErr != nil {
					cleanup()
					return nil, writeErr
				}
			}
			size += int64(n)
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			cleanup()
			return nil, err
		}
		if n == 0 {
			continue
		}
	}
	if file == nil {
		return &memorySource{chunks: chunks, size: size, budget: options.Budget, reserved: memoryReserved}, nil
	}
	path := file.Name()
	if err := file.Sync(); err != nil {
		cleanup()
		return nil, err
	}
	if err := file.Close(); err != nil {
		cleanup()
		return nil, err
	}
	file = nil
	return &fileSource{path: path, size: size, remove: true, budget: options.Budget, reserved: spoolReserved}, nil
}

func ensureDiskReserve(dir string, reserveBytes, incoming int64) error {
	if reserveBytes <= 0 {
		return nil
	}
	if dir == "" {
		dir = os.TempDir()
	}
	dir, err := filepath.Abs(dir)
	if err != nil {
		return err
	}
	var stat syscall.Statfs_t
	if err = syscall.Statfs(dir, &stat); err != nil {
		return fmt.Errorf("stat spool filesystem: %w", err)
	}
	available := int64(stat.Bavail) * int64(stat.Bsize)
	if available-incoming < reserveBytes {
		return ErrDiskReserve
	}
	return nil
}

func max64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}
package bodysource

import (
	"bytes"
	"context"
	"errors"
	"io"
	"os"
	"sync"
)

// SpoolBuffer is a replayable writer that spills from bounded memory to one file.
type SpoolBuffer struct {
	ctx            context.Context
	options        CaptureOptions
	memory         bytes.Buffer
	file           *os.File
	size           int64
	memoryReserved int64
	spoolReserved  int64
	sealed         bool
	closed         bool
	err            error
	mu             sync.Mutex
}

func NewSpoolBuffer(ctx context.Context, options CaptureOptions) (*SpoolBuffer, error) {
	if options.MaxBytes <= 0 {
		return nil, ErrBodyTooLarge
	}
	if ctx == nil {
		ctx = context.Background()
	}
	if options.MemoryThreshold < 0 {
		options.MemoryThreshold = 0
	}
	if options.TempFileNamePrefix == "" {
		options.TempFileNamePrefix = "codex-pool-buffer-*"
	}
	return &SpoolBuffer{ctx: ctx, options: options}, nil
}

func (b *SpoolBuffer) Write(p []byte) (int, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.closed || b.sealed {
		return 0, ErrClosed
	}
	if b.err != nil {
		return 0, b.err
	}
	if err := b.ctx.Err(); err != nil {
		b.err = err
		return 0, err
	}
	if int64(len(p)) > b.options.MaxBytes-b.size {
		b.err = ErrBodyTooLarge
		return 0, b.err
	}
	if b.file == nil && b.size+int64(len(p)) <= b.options.MemoryThreshold && b.options.Budget.reserveMemory(int64(len(p))) {
		b.memoryReserved += int64(len(p))
		n, err := b.memory.Write(p)
		b.size += int64(n)
		if err != nil {
			b.err = err
		}
		return n, err
	}
	if b.file == nil {
		if err := b.spillLocked(); err != nil {
			b.err = err
			return 0, err
		}
	}
	if !b.options.Budget.reserveSpool(int64(len(p))) {
		b.err = ErrSpoolBudget
		return 0, b.err
	}
	b.spoolReserved += int64(len(p))
	n, err := writeFull(b.file, p)
	b.size += int64(n)
	if err != nil {
		b.err = err
	}
	return n, err
}

func (b *SpoolBuffer) spillLocked() error {
	if err := ensureDiskReserve(b.options.TempDir, b.options.MinDiskFreeBytes, b.options.MaxBytes); err != nil {
		return err
	}
	if !b.options.Budget.reserveSpool(b.size) {
		return ErrSpoolBudget
	}
	file, err := os.CreateTemp(b.options.TempDir, b.options.TempFileNamePrefix)
	if err != nil {
		b.options.Budget.releaseSpool(b.size)
		return err
	}
	if _, err = writeFull(file, b.memory.Bytes()); err != nil {
		_ = file.Close()
		_ = os.Remove(file.Name())
		b.options.Budget.releaseSpool(b.size)
		return err
	}
	b.file = file
	b.spoolReserved = b.size
	b.memory.Reset()
	b.options.Budget.releaseMemory(b.memoryReserved)
	b.memoryReserved = 0
	return nil
}

func writeFull(w io.Writer, p []byte) (int, error) {
	written := 0
	for len(p) > 0 {
		n, err := w.Write(p)
		written += n
		p = p[n:]
		if err != nil {
			return written, err
		}
		if n == 0 {
			return written, io.ErrShortWrite
		}
	}
	return written, nil
}

func (b *SpoolBuffer) Size() int64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.size
}

func (b *SpoolBuffer) Open() (io.ReadCloser, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.closed {
		return nil, ErrClosed
	}
	if b.err != nil {
		return nil, b.err
	}
	b.sealed = true
	if b.file != nil {
		if err := b.file.Sync(); err != nil {
			return nil, err
		}
		return os.Open(b.file.Name())
	}
	return io.NopCloser(bytes.NewReader(b.memory.Bytes())), nil
}

func (b *SpoolBuffer) Spilled() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.file != nil
}

func (b *SpoolBuffer) Close() error {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.closed {
		return nil
	}
	b.closed = true
	var closeErr error
	if b.file != nil {
		path := b.file.Name()
		closeErr = b.file.Close()
		if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
			closeErr = errors.Join(closeErr, err)
		}
	}
	b.options.Budget.releaseMemory(b.memoryReserved)
	b.options.Budget.releaseSpool(b.spoolReserved)
	b.memory.Reset()
	return closeErr
}
