		chunks = nil
		options.Budget.releaseMemory(memoryReserved)
		memoryReserved = 0
		return nil
	}
	var spoolBuffer []byte
	for {
		if err := ctx.Err(); err != nil {
			cleanup()
			return nil, err
		}
		var chunk []byte
		if file != nil {
			if spoolBuffer == nil {
				spoolBuffer = make([]byte, chunkSize)
			}
			chunk = spoolBuffer
		} else {
			chunk = make([]byte, chunkSize)
