			if int64(n) > options.MaxBytes-size {
				cleanup()
				return nil, ErrBodyTooLarge
			}
			chunk = chunk[:n]
			if file == nil && size+int64(n) <= threshold && options.Budget.reserveMemory(int64(n)) {
