	if err := file.Sync(); err != nil {
		cleanup()
		return nil, err
	}
	if err := file.Close(); err != nil {
		cleanup()
		return nil, err
	}
	file = nil
	options.Budget.recordCapture(size, true)
	return &fileSource{path: path, size: size, remove: true, budget: options.Budget, reserved: spoolReserved}, nil
