func (s *jsonMetaScanner) skipSpace() error {
	for {
		b, err := s.peek()
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return err
		}
		if b != ' ' && b != '\t' && b != '\r' && b != '\n' {
			return nil
		}
		if _, err = s.readByte(); err != nil {
			return err
		}
	}
