func TestCaptureJSONConsumesOnceAndReplays(t *testing.T) {
	body := `{"model":"gpt-5.6-sol","stream":true,"input":"` + strings.Repeat("x", 1<<20) + `"}`
	budget := NewBudget(64<<10, 2<<20)
	source, meta, err := CaptureJSON(context.Background(), strings.NewReader(body), CaptureOptions{MaxBytes: 2 << 20, MemoryThreshold: 64 << 10, TempDir: t.TempDir(), Budget: budget}, []byte("key"))
	if err != nil {
