	for _, body := range []string{``, `[]`, `{"a":01}`, `{"a":"\x"}`, `{"a":true} trailing`, `{"a":[1,]}`} {
		if _, err := ScanJSON(context.Background(), Bytes([]byte(body)), nil); err == nil {
