func decodeJSONString(raw []byte) (string, bool) {
	if len(raw) == 0 || raw[0] != '"' {
		return "", false
	}
	decoded, err := strconv.Unquote(string(raw))
	return decoded, err == nil
}

func (s *jsonMetaScanner) scanValue(depth int, capture bool) (scannedValue, error) {
