func reserve(used *atomic.Int64, limit, n int64) bool {
	if n <= 0 {
		return true
	}
	for {
		current := used.Load()
		if limit > 0 && (current > limit-n) {
			return false
		}
		if used.CompareAndSwap(current, current+n) {
			return true
		}
	}
}

type CaptureOptions struct {
