	if w.status == 0 {
		w.status = http.StatusOK
	}
	if w.status >= http.StatusBadRequest || !w.stream {
		return
	}
	w.commitHeaders()
	if flusher, ok := w.downstream.(http.Flusher); ok {
		flusher.Flush()
	}
}

func (w *userGroupAttemptWriter) Status() int {
	if w.status == 0 {
		return http.StatusOK
	}
	return w.status
}

