	req := Request{Body: bodysource.Bytes([]byte(`{}`)), BodyMeta: meta}
	setRequestBody(&req, []byte(`{"changed":true}`))
	if req.BodyMeta != nil {
		t.Fatal("body metadata survived replacement")
	}
}

