	UpdatedAt      int64  `json:"updated_at"`
}

// GoalTurn is the atomic successful-terminal write.  CheckpointPayload is the stable
// request envelope without turn history; SegmentPayload is exactly one completed turn
// (the current input and upstream output), so the common path never copies history.
type GoalTurn struct {
	Protocol          string
	ParentGoalID      string
	BranchHash        string
	DownstreamKeyHash string
	WorkspaceHash     string
	InitialGoalHash   string
	ResponseID        string
	Aliases           []GoalAlias
	// ResolutionAliasSets are ordered strongest-to-weakest identity candidates.
	// CommitGoalTurn resolves the first set that actually has a durable match;
	// critically, it never unions weak client/session aliases with a concrete
	// thread identity.  This prevents two independent CLI conversations that
	// happen to share a process/session marker from being merged into one goal.
	// Existing callers that leave this empty retain the legacy single-set behavior.
	ResolutionAliasSets [][]GoalAlias
	CheckpointPayload   string
	SegmentPayload      string
	WorkingState        string
	AwaitingTool        bool
	ExpiresAt           int64
	StorageMaxBytes     int64
	CompressionStages   int
}

type GoalResolution struct {
	Session    GoalSession
	Candidates []string
}

type GoalDetail struct {
	Session         GoalSession `json:"session"`
	CheckpointCount int64       `json:"checkpoint_count"`
	SegmentCount    int64       `json:"segment_count"`
	PayloadBytes    int64       `json:"payload_bytes"`
	LatestRun       *GoalRun    `json:"latest_run,omitempty"`
}

// GoalMetrics contains only aggregate lifecycle counters. It is safe for the admin
// surface and diagnostics bundle because it never reads encrypted checkpoint bodies,
// aliases, tool results, or summary text.
type GoalMetrics struct {
	Sessions                  int64 `json:"sessions"`
	StorageBytes              int64 `json:"storage_bytes"`
	ResumeRecovered           int64 `json:"resume_recovered"`
	ResumeAmbiguous           int64 `json:"resume_ambiguous"`
	StreamTerminalSynthesized int64 `json:"stream_terminal_synthesized"`
	PersistenceDegraded       int64 `json:"persistence_degraded"`
}

func hashGoalValue(kind, value string) string {
	s := sha256.Sum256([]byte(strings.TrimSpace(kind) + "\x00" + strings.TrimSpace(value)))
	return hex.EncodeToString(s[:])
}

func hashGoalPayload(payload string) string {
	s := sha256.Sum256([]byte(payload))
	return hex.EncodeToString(s[:])
}

func newGoalID(prefix string) string {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		// crypto/rand failure is exceptionally rare.  Keep the id collision-resistant
		// enough for a local SQLite primary key and let the insert report a collision.
		return fmt.Sprintf("%s_%x", prefix, time.Now().UnixNano())
	}
	return prefix + "_" + hex.EncodeToString(b)
}

func normalizedGoalAliases(in []GoalAlias) []GoalAlias {
	seen := make(map[string]bool, len(in))
	out := make([]GoalAlias, 0, len(in))
	for _, alias := range in {
		alias.Type = strings.TrimSpace(strings.ToLower(alias.Type))
		alias.Value = strings.TrimSpace(alias.Value)
		if alias.Type == "" || alias.Value == "" {
			continue
		}
		h := hashGoalValue(alias.Type, alias.Value)
		if seen[h] {
			continue
		}
		seen[h] = true
		out = append(out, alias)
	}
	return out
}

func (s *Store) resolveGoalAliases(ctx context.Context, q sqlQueryer, aliases []GoalAlias) (GoalResolution, error) {
	aliases = normalizedGoalAliases(aliases)
	if len(aliases) == 0 {
		return GoalResolution{}, ErrGoalNotFound
	}
	args := make([]interface{}, 0, len(aliases)+1)
	marks := make([]string, 0, len(aliases))
	for _, alias := range aliases {
		marks = append(marks, "?")
		args = append(args, hashGoalValue(alias.Type, alias.Value))
	}
	args = append(args, Now())
	query := `SELECT DISTINCT s.id, s.protocol, s.parent_goal_id, s.branch_hash,
 s.downstream_key_hash, s.workspace_hash, s.initial_goal_hash, s.last_response_hash,
 s.state, s.current_checkpoint_id, s.encrypted_working_state, s.expires_at, s.created_at, s.updated_at
 FROM goal_alias a JOIN goal_session s ON s.id=a.goal_id
 WHERE a.alias_hash IN (` + strings.Join(marks, ",") + `) AND s.expires_at>?`
	rows, err := q.QueryContext(ctx, query, args...)
	if err != nil {
		return GoalResolution{}, err
	}
	defer rows.Close()
	var out []GoalSession
	for rows.Next() {
		var item GoalSession
		var encrypted string
		if err := rows.Scan(&item.ID, &item.Protocol, &item.ParentGoalID, &item.BranchHash,
			&item.DownstreamKeyHash, &item.WorkspaceHash, &item.InitialGoalHash, &item.LastResponseHash,
			&item.State, &item.CurrentCheckpoint, &encrypted, &item.ExpiresAt, &item.CreatedAt, &item.UpdatedAt); err != nil {
			return GoalResolution{}, err
		}
		item.WorkingState = s.openToken(encrypted)
		out = append(out, item)
	}
	if err := rows.Err(); err != nil {
		return GoalResolution{}, err
	}
	if len(out) == 0 {
		return GoalResolution{}, ErrGoalNotFound
	}
	if len(out) > 1 {
		ids := make([]string, 0, len(out))
		for _, item := range out {
			ids = append(ids, item.ID)
		}
		sort.Strings(ids)
		return GoalResolution{Candidates: ids}, ErrGoalAmbiguous
	}
	return GoalResolution{Session: out[0]}, nil
}

// sqlQueryer lets alias resolution use either the normal read pool or the commit
// transaction without duplicating the collision-sensitive query.
type sqlQueryer interface {
	QueryContext(context.Context, string, ...interface{}) (*sql.Rows, error)
}

func (s *Store) ResolveGoalAliases(ctx context.Context, aliases []GoalAlias) (GoalResolution, error) {
	return s.resolveGoalAliases(ctx, s.rdb, aliases)
}

// ResolveGoalAliasSets applies the caller's documented identity precedence.  A
// complete set is deliberately resolved together: conflicting concrete aliases in
// the same precedence level remain an ambiguity, while a missing stronger alias
// may fall through to a persisted response/turn alias.  It is used by the relay
// before recovery and by CommitGoalTurn inside its write transaction.
func (s *Store) ResolveGoalAliasSets(ctx context.Context, aliasSets [][]GoalAlias) (GoalResolution, error) {
	return s.resolveGoalAliasSets(ctx, s.rdb, aliasSets)
}

func (s *Store) resolveGoalAliasSets(ctx context.Context, q sqlQueryer, aliasSets [][]GoalAlias) (GoalResolution, error) {
	for _, aliases := range aliasSets {
		aliases = normalizedGoalAliases(aliases)
		if len(aliases) == 0 {
			continue
		}
		resolution, err := s.resolveGoalAliases(ctx, q, aliases)
		if errors.Is(err, ErrGoalNotFound) {
			continue
		}
		return resolution, err
	}
	return GoalResolution{}, ErrGoalNotFound
}

// ResolveFallbackGoal is deliberately narrow: only the exact key/workspace/initial
// fingerprint triple is allowed and callers must reject more than one result.  It is
// never a model-name, cache-prefix, or account-affinity guess.
func (s *Store) ResolveFallbackGoal(ctx context.Context, downstreamKeyHash, workspaceHash, initialGoalHash string) (GoalResolution, error) {
	if strings.TrimSpace(downstreamKeyHash) == "" || strings.TrimSpace(workspaceHash) == "" || strings.TrimSpace(initialGoalHash) == "" {
		return GoalResolution{}, ErrGoalNotFound
	}
	rows, err := s.rdb.QueryContext(ctx, `SELECT id, protocol, parent_goal_id, branch_hash,
 downstream_key_hash, workspace_hash, initial_goal_hash, last_response_hash, state,
 current_checkpoint_id, encrypted_working_state, expires_at, created_at, updated_at
 FROM goal_session WHERE downstream_key_hash=? AND workspace_hash=? AND initial_goal_hash=? AND expires_at>?`,
		downstreamKeyHash, workspaceHash, initialGoalHash, Now())
	if err != nil {
		return GoalResolution{}, err
	}
	defer rows.Close()
	var matches []GoalSession
	for rows.Next() {
		var item GoalSession
		var encrypted string
		if err := rows.Scan(&item.ID, &item.Protocol, &item.ParentGoalID, &item.BranchHash,
			&item.DownstreamKeyHash, &item.WorkspaceHash, &item.InitialGoalHash, &item.LastResponseHash,
			&item.State, &item.CurrentCheckpoint, &encrypted, &item.ExpiresAt, &item.CreatedAt, &item.UpdatedAt); err != nil {
			return GoalResolution{}, err
		}
		item.WorkingState = s.openToken(encrypted)
		matches = append(matches, item)
	}
	if err := rows.Err(); err != nil {
		return GoalResolution{}, err
	}
	if len(matches) == 0 {
		return GoalResolution{}, ErrGoalNotFound
	}
	if len(matches) > 1 {
		ids := make([]string, 0, len(matches))
		for _, item := range matches {
			ids = append(ids, item.ID)
		}
		sort.Strings(ids)
		return GoalResolution{Candidates: ids}, ErrGoalAmbiguous
	}
	return GoalResolution{Session: matches[0]}, nil
}

// CommitGoalTurn atomically creates/binds the goal, its response alias and a single
// incremental segment.  The old context_journal is intentionally not touched here;
// callers dual-write it after this transaction so a v1 row can never make a v2 commit
// appear successful when it is not.
func (s *Store) CommitGoalTurn(ctx context.Context, turn GoalTurn) (GoalSession, error) {
	turn.Protocol = strings.TrimSpace(strings.ToLower(turn.Protocol))
	if turn.Protocol == "" || strings.TrimSpace(turn.CheckpointPayload) == "" || strings.TrimSpace(turn.SegmentPayload) == "" {
		return GoalSession{}, errors.New("invalid goal turn")
	}
	if turn.ExpiresAt <= Now() {
		return GoalSession{}, errors.New("goal turn expiry must be in the future")
	}
	aliases := normalizedGoalAliases(turn.Aliases)
	if strings.TrimSpace(turn.ResponseID) != "" {
		aliases = append(aliases, GoalAlias{Type: "response_id", Value: turn.ResponseID})
		aliases = normalizedGoalAliases(aliases)
	}
	now := Now()
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return GoalSession{}, err
	}
	defer tx.Rollback()

	// Expired completed/retryable work is always reclaimed before rejecting a new
	// checkpoint.  Active runs never participate in eviction.
	if _, err := tx.ExecContext(ctx, `DELETE FROM goal_session WHERE expires_at<=? AND id NOT IN (SELECT goal_id FROM goal_run WHERE state IN ('running','compacting','awaiting_tool_result') AND lease_expires_at>?)`, now, now); err != nil {
		return GoalSession{}, err
	}
	// A Codex child branch always resolves by its own concrete thread first.  The
	// parent/root alias remains owned by the root session and is relationship data,
	// never an instruction to merge a child's raw segment stream into its parent.
	resolutionSets := turn.ResolutionAliasSets
	if len(resolutionSets) == 0 {
		// Backward-compatible storage callers did not supply priority sets. A
		// concrete branch remains the only special case in that legacy shape.
		resolutionSets = [][]GoalAlias{aliases}
		if strings.TrimSpace(turn.BranchHash) != "" {
			branchAliases := make([]GoalAlias, 0, 1)
			for _, alias := range aliases {
				if alias.Type == "codex_branch_thread" {
					branchAliases = append(branchAliases, alias)
				}
			}
			if len(branchAliases) > 0 {
				resolutionSets = [][]GoalAlias{branchAliases}
			}
		}
	}
	resolution, resolveErr := s.resolveGoalAliasSets(ctx, tx, resolutionSets)
	if resolveErr != nil && !errors.Is(resolveErr, ErrGoalNotFound) {
		return GoalSession{}, resolveErr
	}
	var session GoalSession
	var nextSegment, nextCheckpoint int64
	created := errors.Is(resolveErr, ErrGoalNotFound)
	if turn.StorageMaxBytes > 0 {
		var checkpointUsed, segmentUsed int64
		if err := tx.QueryRowContext(ctx, `SELECT COALESCE(SUM(LENGTH(encrypted_payload)),0) FROM goal_checkpoint`).Scan(&checkpointUsed); err != nil {
			return GoalSession{}, err
		}
		if err := tx.QueryRowContext(ctx, `SELECT COALESCE(SUM(LENGTH(encrypted_payload)),0) FROM goal_segment`).Scan(&segmentUsed); err != nil {
			return GoalSession{}, err
		}
		estimate := int64(len(s.sealToken(turn.SegmentPayload)))
		if created {
			estimate += int64(len(s.sealToken(turn.CheckpointPayload)))
		}
		// Existing turns append one segment only; charging their base checkpoint a
		// second time would prematurely reject long jobs even though the chain is
		// incremental.  Encryption overhead is checked conservatively by the next
		// write/cleanup pass without evicting active work.
		used := checkpointUsed + segmentUsed
		if used+estimate > turn.StorageMaxBytes {
			protectedGoalID := ""
			if !created {
				protectedGoalID = resolution.Session.ID
			}
			freed, deleted, reclaimErr := s.reclaimGoalStorageBudget(ctx, tx, protectedGoalID, now, used+estimate-turn.StorageMaxBytes)
			if reclaimErr != nil {
				return GoalSession{}, reclaimErr
			}
			used -= freed
			if deleted > 0 {
				if _, auditErr := tx.ExecContext(ctx, `INSERT INTO audit_log(account_id,account_label,action,state,reason,detail,created_at) VALUES('', '', ?, ?, ?, ?, ?)`,
					"goal_storage_reclaimed", "completed", "storage_budget_lru", fmt.Sprintf("goals=%d bytes=%d", deleted, freed), now); auditErr != nil {
					return GoalSession{}, auditErr
				}
			}
		}
		if used+estimate > turn.StorageMaxBytes {
			return GoalSession{}, ErrGoalStorageBudget
		}
	}
	if created {
		session = GoalSession{
			ID: newGoalID("goal"), Protocol: turn.Protocol, ParentGoalID: strings.TrimSpace(turn.ParentGoalID),
			BranchHash: strings.TrimSpace(turn.BranchHash), DownstreamKeyHash: strings.TrimSpace(turn.DownstreamKeyHash),
			WorkspaceHash: strings.TrimSpace(turn.WorkspaceHash), InitialGoalHash: strings.TrimSpace(turn.InitialGoalHash),
			State: "ready", ExpiresAt: turn.ExpiresAt, CreatedAt: now, UpdatedAt: now,
		}
		// The checkpoint/segment tables intentionally have foreign keys to a goal.
		// Insert the session shell first, then fill current_checkpoint_id in the
		// final upsert below; the entire sequence remains one transaction.
		if _, err := tx.ExecContext(ctx, `INSERT INTO goal_session(id,protocol,parent_goal_id,branch_hash,downstream_key_hash,workspace_hash,initial_goal_hash,last_response_hash,state,current_checkpoint_id,encrypted_working_state,expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
			session.ID, session.Protocol, session.ParentGoalID, session.BranchHash, session.DownstreamKeyHash, session.WorkspaceHash, session.InitialGoalHash, "", session.State, "", s.sealToken(turn.WorkingState), session.ExpiresAt, session.CreatedAt, session.UpdatedAt); err != nil {
			return GoalSession{}, err
		}
		checkpoint := GoalCheckpoint{ID: newGoalID("gcp"), GoalID: session.ID, Sequence: 1, Payload: turn.Chec…871 tokens truncated…text {
	copyAliases := append([]storage.GoalAlias(nil), aliases...)
	return context.WithValue(ctx, goalIdentityAliasesKey{}, copyAliases)
}

func goalIdentityAliases(ctx context.Context) []storage.GoalAlias {
	aliases, _ := ctx.Value(goalIdentityAliasesKey{}).([]storage.GoalAlias)
	return append([]storage.GoalAlias(nil), aliases...)
}

func withGoalOriginalBody(ctx context.Context, body []byte) context.Context {
	return context.WithValue(ctx, goalOriginalBodyKey{}, body)
}

func goalOriginalBody(ctx context.Context, fallback []byte) []byte {
	if body, ok := ctx.Value(goalOriginalBodyKey{}).([]byte); ok && len(body) > 0 {
		return body
	}
	return fallback
}

func hashGoalFingerprint(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return ""
	}
	sum := sha256.Sum256([]byte(value))
	return hex.EncodeToString(sum[:])
}

func (s *Server) goalContinuityEnabled(ctx context.Context) bool {
	return s.flagEnabled(ctx, "goal_continuity_enabled", s.cfg.GoalContinuityEnabled)
}

func (s *Server) goalRetention(ctx context.Context) time.Duration {
	days := s.settingInt(ctx, "goal_retention_days", s.cfg.GoalRetentionDays)
	if days <= 0 {
		days = 7
	}
	return time.Duration(days) * 24 * time.Hour
}

func (s *Server) goalStorageMaxBytes(ctx context.Context) int64 {
	mb := s.settingInt(ctx, "goal_storage_max_mb", s.cfg.GoalStorageMaxMB)
	if mb <= 0 {
		mb = 256
	}
	return int64(mb) << 20
}

func (s *Server) goalCompressionStages(ctx context.Context) int {
	stages := s.settingInt(ctx, "goal_compression_max_stages", s.cfg.GoalCompressionMaxStages)
	if stages <= 0 {
		return 16
	}
	return stages
}

func (s *Server) goalCompressionChunkRatio(ctx context.Context) float64 {
	ratio := s.settingFloat(ctx, "goal_compression_chunk_ratio", s.cfg.GoalCompressionChunkRatio)
	if ratio <= 0 || ratio > 1 {
		return 0.70
	}
	return ratio
}

func (s *Server) goalCompressionConcurrency(ctx context.Context) int {
	limit := s.settingInt(ctx, "goal_compression_concurrency", s.cfg.GoalCompressionConcurrency)
	if limit <= 0 {
		return 1
	}
	return limit
}

const goalCompactionForegroundBudget = 540 * time.Second

// scheduleGoalCompaction starts a bounded, lease-protected local checkpoint job after
// a terminal turn.  It never blocks the client response and never runs two jobs for
// the same active goal; a saturated global limit leaves the committed segment chain
// intact for a later resume/turn to pick up.
func (s *Server) scheduleGoalCompaction(ctx context.Context, goalID string) {
	stages := s.goalCompressionStages(ctx)
	if stages <= 0 {
		return
	}
	session, sessionErr := s.store.GetGoalSession(ctx, goalID)
	if sessionErr != nil || session.State == "awaiting_tool_result" {
		return
	}
	needed, err := s.store.NeedsGoalCompaction(ctx, goalID, stages)
	if err != nil || !needed {
		return
	}
	limit := s.goalCompressionConcurrency(ctx)
	s.goalCompactionMu.Lock()
	if s.goalCompactionActive >= limit {
		s.goalCompactionMu.Unlock()
		_ = s.store.InsertAuditLog(context.Background(), storage.AuditLogRow{Action: "goal_compaction_pending", State: "retryable", Reason: "global_concurrency", Detail: "goal=" + goalID})
		return
	}
	s.goalCompactionActive++
	s.goalCompactionMu.Unlock()
	ratio := s.goalCompressionChunkRatio(ctx)
	supervisor.GoOnce("goal-compaction", func() {
		defer func() {
			s.goalCompactionMu.Lock()
			s.goalCompactionActive--
			s.goalCompactionMu.Unlock()
		}()
		jobCtx, cancel := context.WithTimeout(context.Background(), goalCompactionForegroundBudget)
		defer cancel()
		var finish func(string, string)
		for {
			var leaseErr error
			finish, leaseErr = s.beginGoalRunWithResult(jobCtx, goalID, "compacting")
			if leaseErr == nil {
				break
			}
			if !errors.Is(leaseErr, storage.ErrGoalInProgress) {
				_ = s.store.InsertAuditLog(context.Background(), storage.AuditLogRow{Action: "goal_compaction_failed", State: "retryable", Reason: "lease", Detail: "goal=" + goalID})
				return
			}
			select {
			case <-jobCtx.Done():
				_ = s.store.InsertAuditLog(context.Background(), storage.AuditLogRow{Action: "goal_compaction_pending", State: "retryable", Reason: "lease_wait_budget", Detail: "goal=" + goalID})
				return
			case <-time.After(25 * time.Millisecond):
			}
		}
		finishState, finishCode := "completed", ""
		defer func() { finish(finishState, finishCode) }()
		if err := s.store.SetGoalCompactionState(jobCtx, goalID, "compacting"); err != nil {
			finishState, finishCode = "retryable", "goal_compaction_failed"
			_ = s.store.InsertAuditLog(context.Background(), storage.AuditLogRow{Action: "goal_compaction_failed", State: "retryable", Reason: "state", Detail: "goal=" + goalID})
			return
		}
		completed := false
		defer func() {
			if completed {
				_ = s.store.SetGoalCompactionState(context.Background(), goalID, "ready")
			} else {
				_ = s.store.SetGoalCompactionState(context.Background(), goalID, "retryable")
				finishState = "retryable"
				if finishCode == "" {
					finishCode = "goal_compaction_pending"
				}
			}
		}()
		for {
			if err := jobCtx.Err(); err != nil {
				finishCode = "goal_compaction_pending"
				_ = s.store.InsertAuditLog(context.Background(), storage.AuditLogRow{Action: "goal_compaction_pending", State: "retryable", Reason: "foreground_budget", Detail: "goal=" + goalID})
				return
			}
			needed, err := s.store.NeedsGoalCompaction(jobCtx, goalID, stages)
			if err != nil {
				finishCode = "goal_compaction_failed"
				_ = s.store.InsertAuditLog(context.Background(), storage.AuditLogRow{Action: "goal_compaction_failed", State: "retryable", Reason: "threshold", Detail: "goal=" + goalID})
				return
			}
			if !needed {
				completed = true
				return
			}
			if err := s.store.CompactGoalSegmentsWithRatio(jobCtx, goalID, stages, ratio); err != nil {
				finishCode = "goal_compaction_failed"
				_ = s.store.InsertAuditLog(context.Background(), storage.AuditLogRow{Action: "goal_compaction_failed", State: "retryable", Reason: "checkpoint", Detail: "goal=" + goalID})
				return
			}
		}
	})
}

func (s *Server) goalLeaseDuration(ctx context.Context) time.Duration {
	seconds := s.settingInt(ctx, "goal_lease_seconds", s.cfg.GoalLeaseSeconds)
	if seconds <= 0 {
		seconds = 90
	}
	return time.Duration(seconds) * time.Second
}

func (s *Server) goalHeartbeatDuration(ctx context.Context) time.Duration {
	seconds := s.settingInt(ctx, "goal_heartbeat_seconds", s.cfg.GoalHeartbeatSeconds)
	if seconds <= 0 {
		seconds = 15
	}
	lease := s.goalLeaseDuration(ctx)
	interval := time.Duration(seconds) * time.Second
	if interval >= lease {
		interval = lease / 2
	}
	if interval <= 0 {
		interval = 15 * time.Second
	}
	return interval
}

// beginGoalRun acquires the durable resume lease and maintains its heartbeat for the
// lifetime of a foreground relay.  The returned closer is idempotent from the caller's
// perspective and lets FinishGoalRun preserve retryable state when the stream was
// interrupted after its last checkpoint.
func (s *Server) beginGoalRun(ctx context.Context, goalID, phase string) (func(), error) {
	finish, err := s.beginGoalRunWithResult(ctx, goalID, phase)
	if err != nil {
		return nil, err
	}
	return func() { finish("completed", "") }, nil
}

// beginGoalRunWithResult is the lifecycle-aware variant used by compaction jobs.
// It lets a bounded background stage retain goal_compaction_pending rather than being
// overwritten as completed by a generic deferred cleanup.
func (s *Server) beginGoalRunWithResult(ctx context.Context, goalID, phase string) (func(string, string), error) {
	owner := "goal:" + requestIDFromContext(ctx)
	if owner == "goal:" {
		owner = fmt.Sprintf("goal:%d", time.Now().UnixNano())
	}
	lease := s.goalLeaseDuration(ctx)
	run, err := s.store.AcquireGoalRun(ctx, goalID, owner, phase, lease)
	if err != nil {
		return nil, err
	}
	stop := make(chan struct{})
	done := make(chan struct{})
	interval := s.goalHeartbeatDuration(ctx)
	go func() {
		defer supervisor.Recover("goal-heartbeat")
		defer close(done)
		ticker := time.NewTicker(interval)
