package storage

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"errors"
	"fmt"
	"time"
)

// DiagnosticSnapshot freezes a file-backed SQLite database at one committed WAL
// boundary while the exporter reads through Store's separate read pool. Holding a
// reserved writer transaction prevents later commits, so every read connection sees
// the same committed state. In-memory test stores use one shared connection and
// therefore fall back to a no-op snapshot; production file stores always have a
// distinct WAL read pool.
type DiagnosticSnapshot struct {
	id     string
	conn   *sql.Conn
	closed bool
}

func (s *Store) BeginDiagnosticSnapshot(ctx context.Context) (*DiagnosticSnapshot, error) {
	snapshot := &DiagnosticSnapshot{id: newDiagnosticSnapshotID()}
	if s == nil || s.db == nil {
		return nil, errors.New("diagnostic snapshot store is unavailable")
	}
	if s.rdb == s.db {
		return snapshot, nil
	}
	conn, err := s.db.Conn(ctx)
	if err != nil {
		return nil, err
	}
	if _, err = conn.ExecContext(ctx, "BEGIN IMMEDIATE"); err != nil {
		_ = conn.Close()
		return nil, fmt.Errorf("begin diagnostic SQLite snapshot: %w", err)
	}
	snapshot.conn = conn
	return snapshot, nil
}

func (s *DiagnosticSnapshot) ID() string {
	if s == nil {
		return ""
	}
	return s.id
}

func (s *DiagnosticSnapshot) Close() error {
	if s == nil || s.closed {
		return nil
	}
	s.closed = true
	if s.conn == nil {
		return nil
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	_, rollbackErr := s.conn.ExecContext(ctx, "ROLLBACK")
	closeErr := s.conn.Close()
	return errors.Join(rollbackErr, closeErr)
}

func newDiagnosticSnapshotID() string {
	var value [16]byte
	if _, err := rand.Read(value[:]); err == nil {
		return "diag_" + hex.EncodeToString(value[:])
	}
	return fmt.Sprintf("diag_%x", time.Now().UnixNano())
}

