			if errors.Is(reserveErr, admission.ErrCapacity) {
				rec.Header().Set("Retry-After", "1")
			}
			writeError(rec, status, reserveErr)
			return
		}
		defer release()
	}
	var requestBody bodysource.BodySource
	var bodyMeta bodysource.BodyMeta
	if r.Body != nil && r.Body != http.NoBody {
		var err error
		if requestNeedsBodyMeta(r) {
			requestBody, bodyMeta, err = captureJSONRequestBody(r.Context(), r.Body, s.cfg, s.bodyBudget, s.identitySecretCached)
		} else {
			requestBody, err = captureRequestBody(r.Context(), r.Body, s.cfg, s.bodyBudget)
		}
		_ = r.Body.Close()
		if err != nil {
			status := http.StatusBadRequest
			if errors.Is(err, bodysource.ErrBodyTooLarge) {
				status = http.StatusRequestEntityTooLarge
			} else if errors.Is(err, bodysource.ErrSpoolBudget) || errors.Is(err, bodysource.ErrDiskReserve) {
				status = http.StatusServiceUnavailable
				rec.Header().Set("Retry-After", "1")
			}
			writeError(rec, status, err)
			return
		}
		defer requestBody.Close()
		body, err := requestBody.Open()
		if err != nil {
			writeError(rec, http.StatusInternalServerError, err)
			return
		}
		defer body.Close()
		r.Body = body
		r.GetBody = requestBody.Open
		r.ContentLength = requestBody.Size()
	}
	ctx := contextWithRequestID(r.Context(), requestID)
	if requestBody != nil {
		ctx = contextWithBodySource(ctx, requestBody)
	}
	if bodyMeta.Size > 0 {
		ctx = contextWithBodyMeta(ctx, bodyMeta)
	}
	ctx = contextWithUsageEventID(ctx, newRequestID())
	ctx = contextWithRuntimeSettingsCache(ctx)
	r = r.WithContext(ctx)
	defer func() {
		if v := recover(); v != nil {
			log.Printf("[PANIC] request_id=%s method=%s path=%s remote=%s panic=%v",
				requestID, r.Method, r.URL.Path, r.RemoteAddr, v)
			supervisor.LogPanic("http-request", fmt.Sprintf("%s %s request_id=%s remote=%s panic=%v",
				r.Method, r.URL.Path, requestID, r.RemoteAddr, v))
			if !rec.wrote && !rec.hijacked {
				writeJSON(rec, http.StatusInternalServerError, map[string]interface{}{
					"error": map[string]interface{}{
						"message":    "internal server error",
						"type":       "codex_pool_panic",
						"request_id": requestID,
					},
				})
			}
			return
		}
		if rec.status >= http.StatusInternalServerError {
			log.Printf("[HTTP-ERROR] request_id=%s status=%d method=%s path=%s bytes=%d duration=%s",
				requestID, rec.status, r.Method, r.URL.Path, rec.bytes, time.Since(start).Round(time.Millisecond))
		}
	}()
	s.mux.ServeHTTP(rec, r)
}

func captureRequestBody(ctx context.Context, src io.Reader, cfg config.Config, budget *bodysource.Budget) (bodysource.BodySource, error) {
	return bodysource.Capture(ctx, src, bodysource.CaptureOptions{MaxBytes: cfg.MaxBodyBytes, MemoryThreshold: cfg.BodyMemoryThresholdBytes, TempDir: cfg.BodySpoolDir, MinDiskFreeBytes: cfg.BodyDiskReserveBytes, Budget: budget})
}

func captureJSONRequestBody(ctx context.Context, src io.Reader, cfg config.Config, budget *bodysource.Budget, hmacKey []byte) (bodysource.BodySource, bodysource.BodyMeta, error) {
