// handleAnthropicPassthrough is a transparent authenticated proxy for the extra
// Anthropic endpoints that Claude Code skills / code-execution depend on but that
// the message relay never served — so they 404'd and "无法访问官方 skills":
//
//   - the Files API (/v1/files…, multipart uploads + download)
//   - /v1/skills…             (skills-2025-10-02)
//   - /v1/agents…             (managed-agents-2026-04-01)
//   - /v1/environments… , /v1/sessions…  (code-execution containers)
//
// Unlike /v1/messages these are NOT message turns: the body is opaque (a multipart
// upload, a JSON skill/agent definition, or empty for a GET/DELETE) and must be
// forwarded byte-for-byte — no cloak/virtualization, no model override, no Anthropic-
// Beta superset injection. The client's own Content-Type / Accept / Anthropic-Beta /
// Anthropic-Version ride through verbatim (PassThrough on the upstream request); we
// only select a Claude account, attach its auth + the Claude Code identity fingerprint,
// and route through the account's egress (incl. sidecar JA3 / WARP chain). The upstream
// response is forwarded with header leak-scrub but WITHOUT body scrubbing — the bytes
// are file content / resource definitions, not a model turn that could leak the virtual
// identity.
//
// Account stickiness: passthrough resources are account-scoped (a file_id only resolves
// on the account that uploaded it). ExtractAffinityKey folds in the downstream identity,
// so every passthrough call from one downstream api key pins to one account — keeping a
// file's whole lifecycle (upload → reference → delete) on a single upstream account.
func (s *Server) handleAnthropicPassthrough(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet, http.MethodPost, http.MethodDelete, http.MethodPut, http.MethodPatch:
	default:
		methodNotAllowed(w)
		return
	}

	body := bodySourceFromContext(r.Context())
	var raw []byte
	if body == nil && r.Body != nil {
		b, err := readLimited(r.Body, s.cfg.MaxBodyBytes)
		if err != nil {
			writeError(w, http.StatusRequestEntityTooLarge, err)
			return
		}
		raw = b
		body = bodysource.Bytes(raw)
		defer body.Close()
	}

	// Authenticate + resolve the routing group (honors RequireDownstreamKey). The
	// force-model/effort overrides are irrelevant here and never touch the opaque body.
	pol, ok := s.resolveDownstreamPolicy(w, r)
	if !ok {
		return
	}
	hint := normalizeProviderHintLoose(r.Header.Get("X-Pool-Provider"))
	if strings.TrimSpace(r.Header.Get("X-Pool-Provider")) == "" {
		hint = normalizeProviderHintLoose(pol.ProviderHint)
	}
	if hint == "kiro" {
		s.writeCapabilityUnavailable(w, http.StatusBadRequest, "Kiro does not support this Anthropic passthrough endpoint", []string{"kiro_unsupported_endpoint:" + r.URL.Path}, "official_claude_passthrough", "kiro", "Use provider_hint=\"claude\" for Files, Skills, Agents and related endpoints.")
		return
	}

	affinity := routing.ExtractAffinityKey(r, raw)
	resourceAffinity, resourceKind, resourceID := claudeResourceAffinity(r.URL.Path)
	immutableResource := false
	if resourceAffinity.Hash != "" {
		if _, bindingErr := s.store.GetAffinityBinding(r.Context(), resourceAffinity.Hash); bindingErr == nil {
			affinity = resourceAffinity
			immutableResource = true
		} else if !storage.NotFound(bindingErr) {
			writeError(w, http.StatusInternalServerError, bindingErr)
			return
		}
	}
	lease, err := s.scheduler.Select(r.Context(), scheduler.Route{
		Group:             pol.Group,
		Provider:          "claude",
		Affinity:          affinity,
		ImmutableAffinity: immutableResource,
	})
	if err != nil {
		if errors.Is(err, scheduler.ErrBoundAccountUnavailable) {
			writePoolCodeError(w, http.StatusConflict, "bound_account_unavailable", "the account bound to this resource is unavailable")
			return
		}
		s.writePublicNoAccountError(r.Context(), w, http.StatusServiceUnavailable, pol.Group, "claude", "", err)
		return
	}
	leaseReleased := false
	releaseLease := func() {
		if leaseReleased {
			return
		}
	ctx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, strings.TrimRight(sidecarEndpoint, "/")+"/cookies", bytes.NewReader(payload))
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/json")
	client, err := c.sidecarHTTPClient()
	if err != nil {
		return err
	}
	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<16))
	if resp.StatusCode >= 400 {
		return fmt.Errorf("sidecar /cookies status %d", resp.StatusCode)
	}
	return nil
}

type Request struct {
	Method   string
	Provider string // "" / "codex" (default), "claude", or a custom provider id
	// BaseURL is set for a custom OpenAI-compatible provider: the upstream API base
	// (including any "/v1" prefix). doOpenAICompatible appends DownstreamPath
	// (/chat/completions or /models). Ignored by the codex/claude paths, which derive
	// their base from config.
	BaseURL string
	// TransportProfile selects the first-party request identity simulated for a
	// custom provider: generic, codex_cli, or claude_code.
	TransportProfile string
	DownstreamPath   string
	Headers          http.Header
	Body             bodysource.BodySource
	BodyMeta         *bodysource.BodyMeta
	bodyBytes        []byte
	bodyLoaded       bool
	Account          storage.Account
	Token            storage.AccountToken
	Egress           storage.EgressProfile
	CookieJarKey     string
	// Model is the downstream-requested model name (may include thinking suffix like
	// "claude-opus-4-8(high)"). Used by thinking configuration resolution to apply
	// model-specific overrides and parse suffix-based thinking hints.
	Model string
	// OSHint, when set ("Mac OS"/"Linux"/"Windows" or aliases), makes the
	// account's virtual identity present that OS family instead of the VPS host
	// (the "downstream" identity source). Empty = use the detected host.
	OSHint string
	// CodexClientVersion, when set, overrides the synthesized Codex CLI version on
	// THIS request's User-Agent and `version` header (OAuth accounts only). Model
	// discovery and version-gated live models use the current client version; empty
	// keeps the normal per-account/default version. Has no effect on API-key traffic.
	CodexClientVersion string
	// CodexResponsesWebSocket sends a Codex Responses turn over the official
	// responses WebSocket beta transport, returning the upstream events as an SSE
	// body to the gateway. It is intended for streaming /v1/responses turns only.
	CodexResponsesWebSocket bool
	// CodexWebSocketSession keeps one upstream WebSocket alive across sequential
	// response.create frames from one downstream WebSocket. Codex 0.144.x performs
	// a generate=false warmup, then references that response id on the same
	// connection; opening a fresh upstream connection per frame loses that state.
	CodexWebSocketSession *CodexResponsesWebSocketSession
	// CodexIdentity is the gateway's immutable, persistence-backed identity
	// snapshot for this logical Responses submission.  It is deliberately public
	// because the API layer owns the durable mapping; HTTP, SSE and WebSocket all
	// consume the same snapshot below. Nil keeps the legacy standalone-client
	// fallback used by focused upstream tests and non-gateway callers.
	CodexIdentity *CodexIdentitySnapshot
	// codexMetadata is an immutable, request-scoped snapshot generated at the Do
	// choke point. HTTP headers, HTTP client_metadata and the WS handshake/body all
	// consume the same snapshot so account-virtualized identifiers cannot drift.
	codexMetadata *codexRequestMetadata
	// PassThrough (Claude provider only) forwards the request to api.anthropic.com as a
	// TRANSPARENT proxy: the client's own Content-Type / Accept / Anthropic-Beta are
	// preserved verbatim and the body is NOT cloaked/virtualized. It is for the extra
	// Anthropic endpoints Claude Code skills / code-execution use — /v1/files (multipart
	// uploads), /v1/skills, /v1/agents|environments|sessions — which are not message
type Response struct {
	StatusCode int
	Header     http.Header
	// Trailer is populated by net/http after Body reaches EOF. Sidecar v2 uses
	// chunked trailers for failures discovered after response headers have already
	// been committed, so callers must inspect it only after consuming Body.
	Trailer http.Header
	Body    io.ReadCloser
}

func (r *Request) loadBody() error {
	if r.bodyLoaded {
		return nil
	}
	if r.Body == nil {
		r.Body = bodysource.Empty()
		r.bodyLoaded = true
		return nil
	}
	body, err := bodysource.ReadAll(r.Body)
	if err != nil {
		return err
	}
	r.bodyBytes, r.bodyLoaded = body, true
	return nil
}

func requestBody(r Request) []byte {
	if r.bodyLoaded {
		return r.bodyBytes
	}
	body, _ := bodysource.ReadAll(r.Body)
	return body
}

func requestStreamTrue(r Request) bool {
	if r.BodyMeta != nil && r.BodyMeta.StreamPresent {
		return r.BodyMeta.Stream
	}
	return bodyStreamTrue(requestBody(r))
}

func setRequestBody(r *Request, body []byte) {
	r.Body = bodysource.Bytes(body)
	r.BodyMeta = nil
	r.bodyBytes, r.bodyLoaded = body, true
