		return nil
	}
	rec := newCodexStreamLedgerRecorder()
	_, _ = rec.Write(raw)
	return rec.ResponseJSON()
}

func (r *codexStreamLedgerRecorder) Write(p []byte) (int, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.buf = append(r.buf, p...)
	for {
		boundary, separatorLen := sseFrameBoundary(r.buf)
		if boundary < 0 {
			break
		}
		frameEnd := boundary + separatorLen
		frame := r.buf[:frameEnd]
		r.observeFrame(frame)
		r.buf = r.buf[frameEnd:]
	}
	if len(r.buf) > streamLedgerMaxPartialFrame {
		r.buf = r.buf[len(r.buf)-streamLedgerMaxPartialFrame:]
	}
	return len(p), nil
}

// finish observes a final valid SSE event even when the upstream omits the
// optional trailing blank line. Truncated JSON remains unrecognized.
func (r *codexStreamLedgerRecorder) finish() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if len(bytes.TrimSpace(r.buf)) == 0 {
		r.buf = nil
		return
	}
	r.observeFrame(r.buf)
	r.buf = nil
}

func (r *codexStreamLedgerRecorder) ResponseJSON() []byte {
	r.mu.Lock()
	defer r.mu.Unlock()
	var root map[string]interface{}
	if r.completed != nil {
		root = make(map[string]interface{}, len(r.completed)+4)
		for key, value := range r.completed {
			root[key] = value
		}
	} else {
		root = map[string]interface{}{}
	}
	if r.id != "" {
		if _, ok := root["id"]; !ok {
			root["id"] = r.id
		}
	}
	if r.model != "" {
		if _, ok := root["model"]; !ok {
			root["model"] = r.model
		}
	}
	if _, ok := root["object"]; !ok {
		root["object"] = "response"
	}
	if _, ok := root["status"]; !ok {
		root["status"] = "completed"
	}
	text := r.currentTextLocked()
	if !hasNonEmptyArray(root["output"]) {
		if output := r.outputItems(text); len(output) > 0 {
			root["output"] = output
		}
	}
	if text != "" {
		if _, ok := root["output_text"]; !ok {
			root["output_text"] = text
		}
	}
	status := strings.ToLower(streamString(root["status"]))
	if !hasNonEmptyArray(root["output"]) && strings.TrimSpace(streamString(root["output_text"])) == "" &&
		status != "failed" && status != "incomplete" && r.id == "" && r.completed == nil {
		return nil
	}
	out, err := json.Marshal(root)
	if err != nil {
		return nil
	}
	return out
}

// reachedTerminal reports whether the stream observed a terminal Responses event,
// including an explicit error event. When false after the upstream body ends, the
// stream was truncated and may be eligible for a continuation.
func (r *codexStreamLedgerRecorder) reachedTerminal() bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.completed != nil
}

// completedSuccessfully distinguishes a real response.completed from every failure
// or incomplete terminal. Only response.completed may advance a goal checkpoint as
// a successful turn.
func (r *codexStreamLedgerRecorder) completedSuccessfully() bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.terminal == "response.completed"
}

func (r *codexStreamLedgerRecorder) terminalContextError() leakfilter.ResponsesContextErrorKind {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.contextError
}

func (r *codexStreamLedgerRecorder) terminalFailure() (leakfilter.CodexFailureFrame, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.failure == nil {
		return leakfilter.CodexFailureFrame{}, false
	}
	failure := *r.failure
	failure.Header = r.failure.Header.Clone()
	failure.Body = append([]byte(nil), r.failure.Body...)
	return failure, true
}

// responseTurnState returns the opaque upstream continuation token observed in a
// response.metadata SSE event. WebSocket Responses transports carry this value in
// the event headers rather than the HTTP response headers, so it must be retained
// separately from the synthesized terminal response JSON.
func (r *codexStreamLedgerRecorder) responseTurnState() string {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.turnState
}

// partialText returns the assistant output text accumulated so far.
func (r *codexStreamLedgerRecorder) partialText() string {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.currentTextLocked()
}

// partialItems reconstructs the assistant output items produced so far (the same shape
// persistContextJournal appends as input for the next turn), used to re-inject the
// partial answer into the continuation request so the model continues instead of
// restarting — keeping the prompt-cache prefix intact.
func (r *codexStreamLedgerRecorder) partialItems() []interface{} {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.outputItems(r.currentTextLocked())
}

// partialItemCount is the number of output items the stream opened, used to offset the
// continuation's output_index so its items never collide with the ones already relayed.
func (r *codexStreamLedgerRecorder) partialItemCount() int {
	r.mu.Lock()
	defer r.mu.Unlock()
	if n := len(r.done); n > len(r.added) {
		return n
	}
	return len(r.added)
}

// metadata returns a consistent copy of the fields consumed after streaming. The
// heartbeat relay reads upstream data on a helper goroutine; a downstream disconnect
// can make streamSSE return while that goroutine is completing its final recorder
// write, so direct field reads would race even though normal EOF is fully drained.
func (r *codexStreamLedgerRecorder) metadata() (string, string, codexStreamRateLimits) {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.id, r.model, r.rateLimits
}

func (r *codexStreamLedgerRecorder) observeFrame(frame []byte) {
	if failure, ok := leakfilter.ParseCodexFailureFrame(frame); ok {
		copyFailure := failure
		copyFailure.Header = failure.Header.Clone()
		copyFailure.Body = append([]byte(nil), failure.Body...)
		r.failure = &copyFailure
		if failure.ContextError != leakfilter.ResponsesContextErrorNone {
			r.contextError = failure.ContextError
		}
	}
	eventType, data := sseFrameEventData(frame)
	if len(data) == 0 || strings.TrimSpace(string(data)) == "[DONE]" {
		return
	}
	var ev map[string]interface{}
	if json.Unmarshal(data, &ev) != nil {
		return
	}
	typ := streamString(ev["type"])
	if typ == "" {
		typ = eventType
	}
	switch typ {
	case "response.metadata":
		r.turnState = firstNonEmpty(r.turnState, codexSSEHeaderValue(ev, "x-codex-turn-state"))
	case "response.created":
		if resp, ok := ev["response"].(map[string]interface{}); ok {
			if id := strings.TrimSpace(streamString(resp["id"])); id != "" {
				r.id = id
			}
			if model := strings.TrimSpace(streamString(resp["model"])); model != "" {
				r.model = model
			}
		}
	case "response.output_text.delta":
		if delta := streamString(ev["delta"]); delta != "" {
			r.text.WriteString(delta)
		}
	case "response.output_item.added":
		if item := ev["item"]; item != nil {
			r.added = append(r.added, item)
		}
	case "response.output_item.done":
		if item := ev["item"]; item != nil {
			r.done = append(r.done, item)
		}
	case "response.completed", "response.incomplete", "response.failed", "response.error", "error":
		r.terminal = typ
		if resp, ok := ev["response"].(map[string]interface{}); ok {
			r.completed = resp
			if id := strings.TrimSpace(streamString(resp["id"])); id != "" {
				r.id = id
			}
			if model := strings.TrimSpace(streamString(resp["model"])); model != "" {
				r.model = model
			}
		} else {
			// A terminal event without a response object is still a real protocol
			// terminal. Treat it as such so EOF compensation does not append a second,
			// misleading "stream closed before response.completed" failure.
			r.completed = ev
			switch typ {
			case "response.completed":
				r.completed["status"] = "completed"
			case "response.incomplete":
				r.completed["status"] = "incomplete"
			default:
				r.completed["status"] = "failed"
			}
		}
		if hasNonEmptyArray(r.completed["output"]) {
			r.added, r.done = nil, nil
		}
		if completedResponseText(r.completed) != "" {
			r.text.Reset()
		}
	case "codex.rate_limits":
		if rl, ok := parseCodexRateLimitsEvent(ev); ok {
			r.rateLimits = rl
		}
	}
}

func codexSSEHeaderValue(event map[string]interface{}, name string) string {
	headers, _ := event["headers"].(map[string]interface{})
	for key, value := range headers {
		if !strings.EqualFold(strings.TrimSpace(key), name) {
			continue
		}
		text, _ := value.(string)
		return strings.TrimSpace(text)
	}
	return ""
}

func (r *codexStreamLedgerRecorder) outputItems(text string) []interface{} {
	var items []interface{}
	if r.completed != nil && hasNonEmptyArray(r.completed["output"]) {
		items = cloneJSONArray(asSlice(r.completed["output"]))
	} else if len(r.done) > 0 {
		items = cloneJSONArray(r.done)
	} else if len(r.added) > 0 {
		items = cloneJSONArray(r.added)
	}
	if strings.TrimSpace(text) != "" {
		for _, rawItem := range items {
			item, _ := rawItem.(map[string]interface{})
			if streamString(item["type"]) != "message" {
				continue
			}
			if strings.TrimSpace(responsesOutputItemText(item)) == "" {
				item["content"] = []interface{}{map[string]interface{}{"type": "output_text", "text": text}}
			}
			return items
		}
		message := map[string]interface{}{
			"type": "message",
			"role": "assistant",
			"content": []interface{}{map[string]interface{}{
				"type": "output_text",
				"text": text,
			}},
		}
		// Responses ordering is reasoning -> assistant message -> function calls.
		// Insert the delta-only message before the first non-reasoning item.
		insertAt := len(items)
		for index, rawItem := range items {
			item, _ := rawItem.(map[string]interface{})
			if streamString(item["type"]) != "reasoning" {
				insertAt = index
				break
			}
		}
		items = append(items, nil)
		copy(items[insertAt+1:], items[insertAt:])
		items[insertAt] = message
	}
	return items
}

func (r *codexStreamLedgerRecorder) currentTextLocked() string {
	if text := completedResponseText(r.completed); text != "" {
		return text
	}
	return r.text.String()
}

func completedResponseText(response map[string]interface{}) string {
	if response == nil {
		return ""
	}
	if text := streamString(response["output_text"]); text != "" {
		return text
	}
	var text strings.Builder
	for _, rawItem := range asSlice(response["output"]) {
		item, _ := rawItem.(map[string]interface{})
		if streamString(item["type"]) == "message" {
			text.WriteString(responsesOutputItemText(item))
		}
	}
	return text.String()
}

func sseFrameEventData(frame []byte) (string, []byte) {
	var eventType string
	var dataLines []string
	for _, rawLine := range bytes.Split(frame, []byte("\n")) {
		line := strings.TrimRight(string(rawLine), "\r")
		switch {
		case strings.HasPrefix(line, "event:"):
			eventType = strings.TrimSpace(strings.TrimPrefix(line, "event:"))
		case strings.HasPrefix(line, "data:"):
			data := strings.TrimPrefix(line, "data:")
			if strings.HasPrefix(data, " ") {
				data = data[1:]
			}
			dataLines = append(dataLines, data)
		}
	}
	if len(dataLines) == 0 {
		return eventType, nil
	}
	return eventType, []byte(strings.Join(dataLines, "\n"))
}

func cloneJSONValue(v interface{}) interface{} {
	if v == nil {
		return nil
	}
	raw, err := json.Marshal(v)
	if err != nil {
		return nil
	}
	var out interface{}
	if json.Unmarshal(raw, &out) != nil {
		return nil
	}
	return out
}

func cloneJSONMap(v map[string]interface{}) map[string]interface{} {
	cloned, _ := cloneJSONValue(v).(map[string]interface{})
	if cloned == nil {
		return map[string]interface{}{}
	}
	return cloned
}

func cloneJSONArray(v []interface{}) []interface{} {
	out := make([]interface{}, 0, len(v))
	for _, item := range v {
		if cloned := cloneJSONValue(item); cloned != nil {
			out = append(out, cloned)
		}
	}
	return out
}

func hasNonEmptyArray(v interface{}) bool {
	arr, ok := v.([]interface{})
	return ok && len(arr) > 0
}

func streamString(v interface{}) string {
	s, _ := v.(string)
	return s
}
package api

import (
	"bytes"
	"context"
	"errors"
	"io"
	"os"

	"codex-account-pool/internal/config"
	"codex-account-pool/internal/leakfilter"
)

var errSSECaptureLimitExceeded = errors.New("sse capture limit exceeded")

type sseCaptureOptions struct {
	MemoryLimit int64
	DiskLimit   int64
	TempDir     string
}

type capturedSSEStream struct {
	buf         bytes.Buffer
	file        *os.File
	size        int64
	diskSize    int64
	memoryLimit int64
	diskLimit   int64
	tempDir     string
}

func captureCodexSSEForFailover(body io.Reader, opts sseCaptureOptions) (*capturedSSEStream, bool, error) {
	return captureSSEForFailoverWithOptions(body, leakfilter.IsRetryableCodexFailureFrame, opts)
}

func captureClaudeSSEForFailover(body io.Reader, opts sseCaptureOptions) (*capturedSSEStream, bool, error) {
	return captureSSEForFailoverWithOptions(body, leakfilter.IsRetryableClaudeErrorFrame, opts)
}

func captureSSEForFailoverWithOptions(body io.Reader, retryableFrame func([]byte) bool, opts sseCaptureOptions) (*capturedSSEStream, bool, error) {
	captured := newCapturedSSEStream(opts)
	frameBuf := make([]byte, 0, 4096)
	tmp := make([]byte, 32*1024)
	for {
		n, readErr := body.Read(tmp)
		if n > 0 {
			chunk := tmp[:n]
			if _, err := captured.Write(chunk); err != nil {
				captured.Close()
				return nil, false, err
			}
			frameBuf = append(frameBuf, chunk...)
			for {
				boundary, separatorLen := sseFrameBoundary(frameBuf)
				if boundary < 0 {
					break
				}
				frameEnd := boundary + separatorLen
				frame := frameBuf[:frameEnd]
				if retryableFrame(frame) {
					return captured, true, nil
				}
				frameBuf = frameBuf[frameEnd:]
			}
			if len(frameBuf) > streamLedgerMaxPartialFrame {
				frameBuf = frameBuf[len(frameBuf)-streamLedgerMaxPartialFrame:]
			}
		}
		if readErr != nil {
			if readErr == io.EOF {
				return captured, false, nil
			}
			return captured, false, readErr
		}
	}
}

func newCapturedSSEStream(opts sseCaptureOptions) *capturedSSEStream {
	if opts.MemoryLimit <= 0 {
		opts.MemoryLimit = config.DefaultStreamFailoverHoldMemoryBytes
	}
	if opts.DiskLimit < 0 {
		opts.DiskLimit = 0
	}
	return &capturedSSEStream{
		memoryLimit: opts.MemoryLimit,
		diskLimit:   opts.DiskLimit,
		tempDir:     opts.TempDir,
	}
}

func (s *Server) streamFailoverCaptureOptions(ctx context.Context) sseCaptureOptions {
	mem := s.cfg.StreamFailoverHoldMemoryBytes
	if mem <= 0 {
		mem = config.DefaultStreamFailoverHoldMemoryBytes
	}
	disk := s.cfg.StreamFailoverHoldDiskBytes
	if disk < 0 {
		disk = 0
	}
	return sseCaptureOptions{
		MemoryLimit: mem,
		DiskLimit:   disk,
		TempDir:     s.cfg.StreamFailoverHoldTempDir,
	}
}

func (c *capturedSSEStream) Write(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}
	if c.file == nil && c.size+int64(len(p)) <= c.memoryLimit {
		n, err := c.buf.Write(p)
		c.size += int64(n)
		return n, err
	}
	if c.diskLimit <= 0 {
		return 0, errSSECaptureLimitExceeded
	}
	if c.file == nil {
		if int64(c.buf.Len()) > c.diskLimit {
			return 0, errSSECaptureLimitExceeded
		}
		f, err := os.CreateTemp(c.tempDir, "codex-account-pool-sse-*")
		if err != nil {
			return 0, err
		}
		if _, err := f.Write(c.buf.Bytes()); err != nil {
			name := f.Name()
			_ = f.Close()
			_ = os.Remove(name)
			return 0, err
		}
		c.diskSize = int64(c.buf.Len())
		c.buf.Reset()
		c.file = f
	}
	if c.diskSize+int64(len(p)) > c.diskLimit {
		return 0, errSSECaptureLimitExceeded
	}
	n, err := c.file.Write(p)
	c.size += int64(n)
	c.diskSize += int64(n)
	return n, err
}

func (c *capturedSSEStream) Reader() (io.Reader, error) {
	if c == nil {
		return bytes.NewReader(nil), nil
	}
	if c.file != nil {
		if _, err := c.file.Seek(0, io.SeekStart); err != nil {
			return nil, err
		}
		return c.file, nil
	}
	return bytes.NewReader(c.buf.Bytes()), nil
}

func (c *capturedSSEStream) Head(limit int) []byte {
	if c == nil || limit <= 0 {
		return nil
	}
	if c.file == nil {
		b := c.buf.Bytes()
		if len(b) > limit {
			b = b[:limit]
		}
		return append([]byte(nil), b...)
	}
	cur, _ := c.file.Seek(0, io.SeekCurrent)
	defer func() { _, _ = c.file.Seek(cur, io.SeekStart) }()
	if _, err := c.file.Seek(0, io.SeekStart); err != nil {
		return nil
	}
	buf := make([]byte, limit)
	n, _ := io.ReadFull(c.file, buf)
	return buf[:n]
}

func (c *capturedSSEStream) Close() {
	if c == nil || c.file == nil {
		return
	}
	name := c.file.Name()
	_ = c.file.Close()
	_ = os.Remove(name)
	c.file = nil
}
package api

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strconv"
	"strings"

	"codex-account-pool/internal/prompt"
	"codex-account-pool/internal/streamrewrite"
)

type responsesAnthropicToolStream struct {
	blockIndex int
	id         string
	itemID     string
	name       string
	namespace  string
	kind       prompt.ResponsesToolKind
	arguments  strings.Builder
	started    bool
	closed     bool
}

type responsesAnthropicReasoningStream struct {
	blockIndex int
	item       map[string]interface{}
	text       strings.Builder
	started    bool
	closed     bool
}

// responsesStreamToAnthropicSSE is the native Codex Responses -> Claude Messages
// stream bridge. Unlike the old Responses -> Chat -> Messages chain, it preserves
// encrypted reasoning, parallel tool identity, complete tool arguments, cache usage,
// incomplete status, and upstream error events.
func responsesStreamToAnthropicSSE(w http.ResponseWriter, body io.Reader, requestedModel string, toolNames map[string]string, inheritModelTools map[string]bool, scrubber *streamrewrite.Matcher) map[string]interface{} {
	flusher, _ := w.(http.Flusher)
	emit := func(event string, payload map[string]interface{}) {
		payload["type"] = event
		encoded, _ := json.Marshal(payload)
		_, _ = io.WriteString(w, "event: "+event+"\n")
		_, _ = io.WriteString(w, "data: ")
		_, _ = w.Write(encoded)
		_, _ = io.WriteString(w, "\n\n")
		if flusher != nil {
			flusher.Flush()
		}
	}

	messageID := "msg_pool_codex"
	model := requestedModel
	started := false
	terminal := false
	sawText := false
	nextBlock := 0
	textBlock := -1
	textOpen := false
	hasTools := false
	var usage map[string]interface{}
	toolsByKey := map[string]*responsesAnthropicToolStream{}
	tools := make([]*responsesAnthropicToolStream, 0, 4)
	reasoningByKey := map[string]*responsesAnthropicReasoningStream{}
	reasoning := make([]*responsesAnthropicReasoningStream, 0, 2)
	bridgePlan := prompt.NewResponsesToolBridgePlan()

	ensureStarted := func() {
		if started {
			return
		}
		startUsage := map[string]interface{}{"input_tokens": int64(0), "output_tokens": int64(0)}
		if usage != nil {
			for key, value := range usage {
				if key != "output_tokens" {
					startUsage[key] = value
				}
			}
		}
		emit("message_start", map[string]interface{}{"message": map[string]interface{}{
			"id": messageID, "type": "message", "role": "assistant", "model": model,
			"content": []interface{}{}, "stop_reason": nil, "stop_sequence": nil, "usage": startU…2476 tokens truncated…ing(streamString(event["delta"]))
			}
		case "response.function_call_arguments.done":
			state := lookupTool(event)
			fallback := streamString(firstNonEmptyInterface(event["arguments"], mapValueFromNested(event, "item", "arguments")))
			flushToolArguments(state, fallback)
		case "response.custom_tool_call_input.delta":
			if state := lookupTool(event); state != nil && state.kind == prompt.ResponsesToolCustom {
				state.arguments.WriteString(streamString(event["delta"]))
			}
		case "response.custom_tool_call_input.done":
			state := lookupTool(event)
			fallback := streamString(firstNonEmptyInterface(event["input"], mapValueFromNested(event, "item", "input")))
			flushToolArguments(state, fallback)
		case "response.reasoning_summary_text.delta", "response.reasoning_text.delta", "response.reasoning.delta":
			state := getReasoning(event, nil)
			delta := streamString(event["delta"])
			if delta != "" {
				startReasoning(state)
				state.text.WriteString(delta)
				emit("content_block_delta", map[string]interface{}{
					"index": state.blockIndex, "delta": map[string]interface{}{"type": "thinking_delta", "thinking": scrubber.ReplaceString(delta)},
				})
			}
		case "response.output_item.done":
			item, _ := event["item"].(map[string]interface{})
			switch streamString(mapValue(item, "type")) {
			case "reasoning":
				finishReasoning(getReasoning(event, item), item)
			case "function_call":
				state := lookupTool(event)
				if state == nil {
					state = registerTool(event, item, prompt.ResponsesToolFunction)
				}
				flushToolArguments(state, streamString(mapValue(item, "arguments")))
			case "custom_tool_call":
				state := lookupTool(event)
				if state == nil {
					state = registerTool(event, item, prompt.ResponsesToolCustom)
				}
				flushToolArguments(state, streamString(mapValue(item, "input")))
			case "tool_search_call":
				if !strings.EqualFold(streamString(mapValue(item, "execution")), "client") {
					break
				}
				state := lookupTool(event)
				if state == nil {
					state = registerTool(event, item, prompt.ResponsesToolSearch)
				}
				arguments, _ := json.Marshal(mapValue(item, "arguments"))
				flushToolArguments(state, string(arguments))
			case "message":
				if !sawText {
					if text := responsesOutputItemText(item); text != "" {
						sawText = true
						index := ensureText()
						emit("content_block_delta", map[string]interface{}{
							"index": index, "delta": map[string]interface{}{"type": "text_delta", "text": scrubber.ReplaceString(text)},
						})
					}
				}
			}
		case "response.completed", "response.incomplete":
			response, _ := event["response"].(map[string]interface{})
			emitTerminal(response, typ)
		case "response.failed", "response.error", "error":
			terminal = true
			emit("error", map[string]interface{}{"error": map[string]interface{}{
				"type": "api_error", "code": "server_error", "message": publicRetryMessage,
			}})
		}
	}

