			var ok bool
			resolvedModel, bootstrap, ok = resolveClaudeRouteModel(candidateRoute, capabilitiesByAccount[account.ID])
			if !ok {
				index.staticCounters.ModelUnsupported++
				continue
			}
		} else if provider == "codex" && capabilityRouteModel(candidateRoute.Model) {
