	count := 2
	var seed uint64
	if !route.FairScheduling && route.Affinity.Hash != "" {
		count = 3
		seed = rendezvous(route.Affinity.Hash, "candidate-table")
	} else {
		s.mu.Lock()
		s.rr++
		seed = uint64(s.rr)
		s.mu.Unlock()
	}
	written := 0
	for written < count {
		seed = xorshift64(seed)
		index := int(seed % uint64(size))
		duplicate := false
		for i := 0; i < written; i++ {
			if indexes[i] == index {
