	return time.Duration(c.StickyWaitMillis) * time.Millisecond
}

func (c Config) SchedulerHeartbeat() time.Duration {
	seconds := c.SchedulerHeartbeatSeconds
	if seconds <= 0 {
		seconds = 15
	}
	return time.Duration(seconds) * time.Second
}

