type redisCoordinatedLease struct {
	coordinator *redisLeaseCoordinator
	request     LeaseRequest
	id          string
	fence       uint64
	keys        []string
	ttl         time.Duration
	stop        chan struct{}
	once        sync.Once
	releaseErr  error
}

func (l *redisCoordinatedLease) FencingToken() uint64 { return l.fence }

func (l *redisCoordinatedLease) renewLoop() {
	interval := l.ttl / 3
	if interval < time.Second {
		interval = time.Second
	}
	timer := time.NewTicker(interval)
	defer timer.Stop()
	for {
		select {
		case <-l.stop:
			return
		case <-timer.C:
			ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			expiry := time.Now().Add(l.ttl).UnixMilli()
			_, _ = l.coordinator.client.Eval(ctx, redisLeaseRenewScript, l.keys, l.id, strconv.FormatUint(l.fence, 10), expiry, l.ttl.Milliseconds()).Result()
			cancel()
		}
	}
}

func (l *redisCoordinatedLease) Release(ctx context.Context) error {
	l.once.Do(func() {
		close(l.stop)
		_, l.releaseErr = l.coordinator.client.Eval(ctx, redisLeaseReleaseScript, l.keys, l.id, strconv.FormatUint(l.fence, 10), l.coordinator.channel).Result()
		if l.releaseErr != nil {
			l.releaseErr = fmt.Errorf("%w: Redis release: %v", ErrLeaseCoordinatorUnavailable, l.releaseErr)
		}
	})
	return l.releaseErr
}

func splitSQLStatements(source string) []string {
	var statements []string
	start := 0
	var single, double, lineComment, blockComment bool
	for index := 0; index < len(source); index++ {
		switch {
		case lineComment:
			lineComment = source[index] != '\n'
		case blockComment:
			if source[index] == '*' && index+1 < len(source) && source[index+1] == '/' {
				blockComment = false
				index++
			}
		case single:
			if source[index] == '\'' {
				if index+1 < len(source) && source[index+1] == '\'' {
					index++
				} else {
					single = false
