		}
	}
}

func TestScanJSONRejectsInvalidAndDeepBodies(t *testing.T) {
	for _, body := range []string{``, `[]`, `{"a":01}`, `{"a":"\x"}`, `{"a":true} trailing`, `{"a":[1,]}`} {
