	allArrived := make(chan struct{})
	capacityArrived := make(chan struct{})
	release := make(chan struct{})
	var allOnce, capacityOnce sync.Once
	capacity := count
	if capacity > 512 {
		capacity = 512
	}
	h := newHarness(t, func(w http.ResponseWriter, r *http.Request) {
		n := arrived.Add(1)
		if n == int64(capacity) {
