	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Error(err)
	}
}

func drainConcurrentErrors(errs <-chan error, limit int) []error {
	out := make([]error, 0, limit)
	for len(out) < limit {
		select {
		case err := <-errs:
			if err != nil {
				out = append(out, err)
			}
		default:
			return out
		}
	}
	return out
}
