	supervisor.GoOnce("async-write-drainer", func() {
		defer s.asyncWG.Done()
		for {
			fn, ok := <-s.asyncWrites
			if !ok {
				return
			}
			batch := []func(){fn}
			timer := time.NewTimer(5 * time.Millisecond)
		collect:
			for len(batch) < 64 {
				select {
				case next, open := <-s.asyncWrites:
					if !open {
						for _, f := range batch {
							runAsyncWrite(f)
						}
						timer.Stop()
						return
					}
					batch = append(batch, next)
				case <-timer.C:
					break collect
				}
			}
			if !timer.Stop() {
				select {
				case <-timer.C:
				default:
				}
			}
			for _, f := range batch {
				runAsyncWrite(f)
			}
		}
	})
	s.asyncWG.Add(1)
	supervisor.GoOnce("usage-batch-writer", func() {
		defer s.asyncWG.Done()
		for first := range s.usageWrites {
			if first.barrier != nil {
				first.barrier <- s.replayUsageJournal(context.Background())
				s.usagePending.Done()
