const (
	defaultSegmentBytes = int64(8 << 20)
	maxRecordBytes      = uint32(16 << 20)
	segmentPrefix       = "usage-"
	segmentSuffix       = ".journal"
	cursorName          = "cursor"
)

var crcTable = crc32.MakeTable(crc32.Castagnoli)

type Record struct {
	Sequence uint64                    `json:"sequence"`
