	file         *os.File
	fileStart    uint64
	fileSize     int64
	next         uint64
	acked        uint64
	closed       bool
}

func Open(dir string, segmentBytes int64) (*Journal, error) {
	dir = filepath.Clean(strings.TrimSpace(dir))
	if dir == "." || dir == "" {
		return nil, errors.New("usage journal directory is empty")
	}
	if segmentBytes <= 0 {
		segmentBytes = defaultSegmentBytes
	}
