		return 0, err
	}
	j.fileSize += frameBytes
	j.next++
	return record.Sequence, nil
}

func (j *Journal) Replay(limit int) ([]Record, error) {
	j.mu.Lock()
	defer j.mu.Unlock()
	if j.closed {
		return nil, errors.New("usage journal is closed")
	}
	if limit <= 0 {
		limit = 256
