					cleanup()
					return nil, ErrSpoolBudget
				}
				spoolReserved += int64(n)
				if _, writeErr := file.Write(chunk); writeErr != nil {
					cleanup()
					return nil, writeErr
				}
			}
			size += int64(n)
		}
