func (f *Factory) cookieJar(key string) *cookiejar.Jar {
	if key == "" {
		return nil
	}
	now := time.Now()
	f.mu.Lock()
	defer f.mu.Unlock()
	for back := f.jarLRU.Back(); back != nil; back = f.jarLRU.Back() {
		entry := back.Value.(*cookieJarEntry)
		if f.cookieJarTTL <= 0 || now.Sub(entry.lastUsed) < f.cookieJarTTL {
			break
		}
		f.jarLRU.Remove(back)
		delete(f.jars, entry.key)
	}
	if element := f.jars[key]; element != nil {
		entry := element.Value.(*cookieJarEntry)
		entry.lastUsed = now
		f.jarLRU.MoveToFront(element)
		return entry.jar
	}
	jar, _ := cookiejar.New(nil)
	element := f.jarLRU.PushFront(&cookieJarEntry{key: key, jar: jar, lastUsed: now})
	f.jars[key] = element
	if f.cookieJarMax > 0 && f.jarLRU.Len() > f.cookieJarMax {
		back := f.jarLRU.Back()
		f.jarLRU.Remove(back)
		delete(f.jars, back.Value.(*cookieJarEntry).key)
	}
	return jar
}

func (f *Factory) applyCookies(key, rawURL string, header fhttp.Header) {
	jar := f.cookieJar(key)
	u, err := url.Parse(rawURL)
	if jar == nil || err != nil || header.Get("Cookie") != "" {
		return
	}
	values := make([]string, 0, 4)
	for _, cookie := range jar.Cookies(u) {
		values = append(values, cookie.Name+"="+cookie.Value)
	}
	if len(values) > 0 {
		header.Set("Cookie", strings.Join(values, "; "))
	}
}

func (f *Factory) storeCookies(key, rawURL string, header stdhttp.Header) {
	jar := f.cookieJar(key)
	u, err := url.Parse(rawURL)
	if jar == nil || err != nil {
		return
	}
	jar.SetCookies(u, (&stdhttp.Response{Header: header}).Cookies())
}

// TLSDialerFor returns the TLS dialer function from a pooled client matching the
// profile in r.  The dialer is used by the WebSocket transport (A4) to open a
// fingerprinted TCP+TLS connection that gorilla/websocket then upgrades.
func (f *Factory) TLSDialerFor(r Request) (tls_client.TLSDialerFunc, error) {
	client, err := f.clientFor(r)
	if err != nil {
		return nil, err
	}
	return client.GetTLSDialer(), nil
}

// CloseIdle releases idle keep-alive connections across all pooled clients.
func (f *Factory) CloseIdle() {
	f.mu.Lock()
	clients := make([]tls_client.HttpClient, 0, len(f.clients))
	for _, c := range f.clients {
		clients = append(clients, c)
	}
	f.mu.Unlock()
	for _, c := range clients {
		c.CloseIdleConnections()
	}
}

func lowered(in []string) []string {
	out := make([]string, len(in))
	for i, s := range in {
		out[i] = toLowerASCII(s)
	}
	return out
}

func toLowerASCII(s string) string {
	b := []byte(s)
	for i := range b {
		if b[i] >= 'A' && b[i] <= 'Z' {
			b[i] += 'a' - 'A'
		}
	}
	return string(b)
}

// toStdHeader converts an fhttp.Header into a standard net/http.Header. fhttp.Header is a
// map[string][]string like net/http.Header, but they are distinct types, so the pool sees
// only the standard library type.
func toStdHeader(h fhttp.Header) stdhttp.Header {
	out := make(stdhttp.Header, len(h))
	for k, vs := range h {
		if k == fhttp.HeaderOrderKey || k == fhttp.PHeaderOrderKey {
			continue
		}
		cp := make([]string, len(vs))
		copy(cp, vs)
		out[k] = cp
	}
	return out
}
func (c *Client) inProcessFingerprint() bool {
	return strings.EqualFold(strings.TrimSpace(c.cfgSnapshot().EgressFingerprintEngine), "inprocess")
}

// cfgSnapshot returns the live config overlay when an admin has pushed one via
// UpdateConfig, otherwise the boot config. Fingerprint/identity read sites use this
// so operator settings changes are hot; stable bootstrap fields (upstream base URL,
// timeouts) may keep reading c.cfg directly.
func (c *Client) cfgSnapshot() *config.Config {
	if p := c.liveCfg.Load(); p != nil {
		return p
	}
	return &c.cfg
}

// UpdateConfig atomically swaps the live config overlay. The caller (the admin
// settings handler) passes the boot config with the current DB setting overrides
// applied; the next upstream request reads the new fingerprint/identity values.
func (c *Client) UpdateConfig(cfg config.Config) {
	c.liveCfg.Store(&cfg)
}

// SidecarEndpoint returns the configured curl_cffi sidecar base URL ("" if none). The
// registration pipeline uses it to route the OpenAI signup flow through browser-JA3
// impersonation.
func (c *Client) SidecarEndpoint() string {
	return c.cfgSnapshot().DefaultSidecarEndpoint
}

func (c *Client) ImportCookies(accountID, egressID, upstreamHost, fallbackKey, cookieHeader string) error {
	u, err := c.resolveCookieTarget(upstreamHost)
	if err != nil {
		return err
	}
	key := fallbackKey
	if key == "" {
		key = accountID + ":" + egressID
	}
	key = key + ":" + u.Host
	jar := c.cookieJarForKey(key)
	jar.SetCookies(u, parseCookieHeader(cookieHeader))
	return nil
}

// resolveCookieTarget turns an operator-supplied upstream host (bare "chatgpt.com",
// a full URL, or "" = the configured Codex upstream) into the URL whose host scopes
// the cookie jar.
func (c *Client) resolveCookieTarget(upstreamHost string) (*url.URL, error) {
	if upstreamHost == "" {
		u, err := url.Parse(c.cfg.UpstreamBaseURL)
		if err != nil {
			return nil, err
		}
		upstreamHost = u.Host
	}
	target := "https://" + upstreamHost + "/"
	if strings.HasPrefix(upstreamHost, "http://") || strings.HasPrefix(upstreamHost, "https://") {
		target = upstreamHost
	}
	return url.Parse(target)
}

// CookieMapFromHeader parses a "name=value; name2=value2" Cookie header into a flat
// name→value map (the shape the curl_cffi sidecar's /cookies store expects).
func CookieMapFromHeader(header string) map[string]string {
	out := map[string]string{}
	for _, ck := range parseCookieHeader(header) {
		out[ck.Name] = ck.Value
	}
	return out
}
