	indexes, _ = s.candidateIndexes.Load().(map[string]*routeCandidateIndex)
	if index := indexes[key]; index != nil && index.selectionGeneration == selection.generation && time.Since(index.builtAt) < candidateIndexTTL {
		return index, nil
