	}
	lease, err := scheduler.Select(ctx, route)
	if err != nil {
		t.Fatal(err)
	}
	defer lease.Release()
	if lease.Account.ID != "fallback-7" || scheduler.Metrics().CandidateFallbacks == 0 {
		t.Fatalf("lease=%s metrics=%+v", lease.Account.ID, scheduler.Metrics())
	}
}
package api

import (
