	raw := []byte(`{"claude_oauth_token_url":"https://console.anthropic.com/v1/oauth/token"}`)
	if err := os.WriteFile(path, raw, 0o600); err != nil {
		t.Fatalf("write config: %v", err)
	}

	cfg, err := Load(path)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
