func claudeCachePrewarmBody(body []byte) ([]byte, bool) {
	var root map[string]interface{}
	if json.Unmarshal(body, &root) != nil {
		return nil, false
	}
	root["max_tokens"] = 0
	root["stream"] = false
	out, err := json.Marshal(root)
	if err != nil {
		return nil, false
	}
	if bytes.Equal(out, body) {
		return out, true
	}
	return out, true
}
