	if err := s.upsertAccountTx(ctx, tx, account, token, now); err != nil {
		return err
	}
	if err := s.upsertAntigravityCredentialsTx(ctx, tx, credentials, now); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return err
	}
	s.tokenCache.Delete(account.ID)
	return nil
}

