package main

import (
	"os"
	"path/filepath"
	"testing"
)

func TestGenerateAndVerifyExactIncompressibleFixtures(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "fixtures")
	if err := generateCommand([]string{"-dir", dir, "-count", "2", "-tokens", "5000", "-tolerance", "0.01", "-model", "gpt-test", "-encoding", "o200k_base"}); err != nil {
		t.Fatal(err)
	}
	manifest, bodies, minTokens, maxTokens, err := verifyFixtures(dir, 2, true)
	if err != nil {
		t.Fatal(err)
	}
	if len(manifest.Fixtures) != 2 || len(bodies) != 2 || minTokens < 4950 || maxTokens > 5050 {
		t.Fatalf("manifest=%d bodies=%d tokens=%d..%d", len(manifest.Fixtures), len(bodies), minTokens, maxTokens)
	}
	if manifest.Fixtures[0].GzipToRawRatio < 0.70 || manifest.Fixtures[1].GzipToRawRatio < 0.70 {
		t.Fatalf("compressible fixtures: %+v", manifest.Fixtures)
	}
}

func TestFixtureVerificationRejectsMutation(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "fixtures")
	if err := generateCommand([]string{"-dir", dir, "-count", "1", "-tokens", "1000", "-tolerance", "0.02"}); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(dir, "fixture-000.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	raw[len(raw)/2] ^= 1
	if err = os.WriteFile(path, raw, 0o600); err != nil {
		t.Fatal(err)
	}
	if _, _, _, _, err = verifyFixtures(dir, 1, false); err == nil {
		t.Fatal("mutated fixture passed verification")
	}
}

func TestSeedCreatesRequestedAccounts(t *testing.T) {
	database := filepath.Join(t.TempDir(), "pool.sqlite3")
	if err := seedCommand([]string{"-database", database, "-accounts", "3"}); err != nil {
		t.Fatal(err)
	}
	store, err := storage.Open(database)
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
	accounts, err := store.ListAccounts(t.Context())
	if err != nil {
		t.Fatal(err)
	}
	if len(accounts) != 3 {
		t.Fatalf("accounts=%d", len(accounts))
	}
}

